-- Generat de scripts/generate-seed-sql.ts din src/data. Nu edita de mână.
-- Catalogul inițial: categorii, produse, sinonime, magazine, locuri de depozitare, rețete.
-- Fără prețuri: prețurile vin doar de la gospodării.

on conflict (id) do update set name = excluded.name, icon = excluded.icon, sort_order = excluded.sort_order, is_food = excluded.is_food, deleted_at = null;

on conflict (id) do update set name = excluded.name, category_id = excluded.category_id, subcategory = excluded.subcategory, default_unit = excluded.default_unit, season_months = excluded.season_months, is_traditional = excluded.is_traditional, is_market_typical = excluded.is_market_typical, allergens = excluded.allergens, piece_grams = excluded.piece_grams, grams_per_ml = excluded.grams_per_ml, deleted_at = null;

on conflict (id) do update set product_id = excluded.product_id, alias = excluded.alias, deleted_at = null;

on conflict (id) do update set name = excluded.name, kind = excluded.kind, deleted_at = null;

on conflict (id) do update set name = excluded.name, sort_order = excluded.sort_order, deleted_at = null;

on conflict (id) do update set name = excluded.name, description = excluded.description, categories = excluded.categories, cuisine = excluded.cuisine, servings = excluded.servings, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes, difficulty = excluded.difficulty, image_url = excluded.image_url, deleted_at = null;

on conflict (id) do update set recipe_id = excluded.recipe_id, product_id = excluded.product_id, quantity = excluded.quantity, unit = excluded.unit, note = excluded.note, optional = excluded.optional, sort_order = excluded.sort_order, deleted_at = null;

on conflict (id) do update set recipe_id = excluded.recipe_id, position = excluded.position, text = excluded.text, deleted_at = null;
