insert into public.recipes (id, name, description, categories, cuisine, servings, prep_minutes, cook_minutes, difficulty, image_url, created_at, updated_at) values
  ('ciorba-de-perisoare', 'Ciorbă de perișoare', 'Ciorbă acrită cu borș, cu perișoare fragede din carne tocată și orez și multă verdeață.', array['supe_ciorbe', 'traditionale', 'pranz', 'carne']::text[], 'romaneasca', 6, 30, 50, 'mediu', '/retete/ciorba-de-perisoare.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-legume', 'Ciorbă de legume', 'O ciorbă ușoară, acrită cu borș, plină de legume de sezon. Bună pentru zilele de post sau când vrei ceva fără carne.', array['supe_ciorbe', 'traditionale', 'pranz', 'vegetariene']::text[], 'romaneasca', 6, 20, 40, 'usor', '/retete/ciorba-de-legume.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-pui', 'Ciorbă de pui a la grec', 'Ciorbă de pui cu orez, îngroșată cu ou și lămâie, fină și mătăsoasă. O ai pe masă în aproape o oră.', array['supe_ciorbe', 'pranz', 'carne']::text[], 'internationala', 6, 15, 45, 'mediu', '/retete/ciorba-de-pui.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-pui-cu-taitei', 'Supă de pui cu tăiței', 'Supa limpede de duminică, cu tăiței fini și legume. Caldă și liniștitoare, pentru toată familia.', array['supe_ciorbe', 'pranz', 'carne']::text[], 'romaneasca', 6, 15, 60, 'usor', '/retete/supa-de-pui-cu-taitei.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-fasole-cu-afumatura', 'Ciorbă de fasole cu afumătură', 'Ciorbă groasă de fasole boabe, cu costiță afumată și boia. Se face în timp, dar merită așteptarea.', array['supe_ciorbe', 'traditionale', 'pranz', 'carne']::text[], 'romaneasca', 6, 20, 120, 'mediu', '/retete/ciorba-de-fasole-cu-afumatura.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-vacuta', 'Ciorbă de văcuță', 'Ciorbă din carne de vită, cu legume și borș, cu gust bogat și curat. Se fierbe încet până carnea se desface singură.', array['supe_ciorbe', 'traditionale', 'pranz', 'carne']::text[], 'romaneasca', 6, 20, 100, 'mediu', '/retete/ciorba-de-vacuta.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-loboda', 'Ciorbă de lobodă', 'O ciorbă de primăvară, verde și răcoroasă, acrită ușor cu borș. Merge bine și fără carne.', array['supe_ciorbe', 'traditionale', 'pranz', 'vegetariene']::text[], 'romaneasca', 6, 15, 30, 'usor', '/retete/ciorba-de-loboda.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-dovleac', 'Supă cremă de dovleac', 'Supă cremoasă și dulceagă de dovleac, bună în zilele răcoroase. Se mixează într-o clipă.', array['supe_ciorbe', 'pranz', 'vegetariene']::text[], 'internationala', 6, 15, 30, 'usor', '/retete/supa-crema-de-dovleac.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-legume', 'Supă cremă de legume', 'Supă fină, făcută din legumele pe care le ai prin casă. Prinde bine și când vrei ceva ușor.', array['supe_ciorbe', 'pranz', 'vegetariene']::text[], 'internationala', 6, 15, 30, 'usor', '/retete/supa-crema-de-legume.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-rosii', 'Supă de roșii', 'Supă de roșii cu gust bun de vară, fină și ușor dulceagă. Merge bine cu crutoane sau cu un strop de smântână.', array['supe_ciorbe', 'pranz', 'vegetariene']::text[], 'internationala', 4, 10, 30, 'usor', '/retete/supa-de-rosii.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bors-de-peste', 'Borș de pește', 'Borș tradițional cu pește de apă dulce, legume și leuștean, acrit cu borș. Clasic pentru zilele de post.', array['supe_ciorbe', 'traditionale', 'pranz', 'peste']::text[], 'romaneasca', 6, 25, 50, 'mediu', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-galuste', 'Supă de găluște', 'Supă de pui cu găluște pufoase de gris, o rețetă simplă din copilărie. Găluștele se fac repede, cu două ingrediente la îndemână.', array['supe_ciorbe', 'traditionale', 'pranz', 'carne']::text[], 'romaneasca', 6, 20, 60, 'mediu', '/retete/supa-de-galuste.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-taraneasca-de-porc', 'Ciorbă țărănească de porc', 'Ciorbă consistentă, cu carne de porc și legume, acrită cu borș. O masă întreagă într-o singură oală.', array['supe_ciorbe', 'traditionale', 'pranz', 'carne']::text[], 'romaneasca', 6, 20, 75, 'mediu', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('omleta-cu-legume', 'Omletă cu legume', 'Omletă pufoasă cu legume, bună pentru un mic dejun consistent. Se face dintr-o singură tigaie.', array['mic_dejun', 'rapide', 'vegetariene']::text[], 'internationala', 2, 10, 10, 'usor', '/retete/omleta-cu-legume.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('oua-ochiuri', 'Ouă ochiuri cu pâine prăjită', 'Mic dejun simplu: ouă ochiuri cu gălbenușul moale și pâine prăjită crocantă. Gata în câteva minute.', array['mic_dejun', 'rapide', 'vegetariene']::text[], 'romaneasca', 2, 5, 8, 'usor', '/retete/oua-ochiuri.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-oua', 'Salată de ouă', 'Salată de ouă fierte cu iaurt și muștar, bună pe pâine sau ca pachet de prânz. O pregătești din timp și ține în frigider.', array['mic_dejun', 'salate', 'rapide', 'vegetariene']::text[], 'internationala', 4, 10, 10, 'usor', '/retete/salata-de-oua.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('terci-de-ovaz-cu-fructe', 'Terci de ovăz cu fructe', 'Terci cald de ovăz, cu lapte, fructe și puțină miere. Mic dejun care te ține sătul până la prânz.', array['mic_dejun', 'rapide', 'vegetariene']::text[], 'internationala', 2, 5, 10, 'usor', '/retete/terci-de-ovaz-cu-fructe.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('clatite', 'Clătite', 'Clătite subțiri și moi, bune cu dulceață, brânză sau miere. Aluatul se face repede, din ingrediente simple.', array['mic_dejun', 'deserturi', 'vegetariene']::text[], 'romaneasca', 4, 15, 20, 'usor', '/retete/clatite.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('sandvis-cu-branza-si-legume', 'Sandviș cu brânză și legume', 'Sandviș rapid, cu brânză proaspătă și legume crocante. Bun pentru dimineață sau pentru pachet.', array['mic_dejun', 'gustari', 'rapide', 'vegetariene']::text[], 'internationala', 2, 10, 0, 'usor', '/retete/sandvis-cu-branza-si-legume.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bulz', 'Bulz ciobănesc', 'Bulz de mămăligă cu brânză în mijloc, copt până se rumenește. O rețetă de la munte, simplă și sățioasă.', array['traditionale', 'pranz', 'vegetariene']::text[], 'romaneasca', 4, 15, 45, 'mediu', '/retete/bulz.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gris-cu-lapte', 'Griș cu lapte', 'Griș cu lapte fierbinte, fin și dulce, ca în copilărie. Se face în 10 minute, cu dulceață sau scorțișoară deasupra.', array['mic_dejun', 'rapide', 'vegetariene']::text[], 'romaneasca', 2, 3, 10, 'usor', '/retete/gris-cu-lapte.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('iaurt-cu-musli-si-fructe', 'Iaurt cu musli și fructe', 'Mic dejun răcoros, fără gătit: iaurt cu musli crocant și fructe. Îl poți pregăti în două minute.', array['mic_dejun', 'rapide', 'vegetariene']::text[], 'internationala', 2, 5, 0, 'usor', '/retete/iaurt-cu-musli-si-fructe.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ochiuri-romanesti-scrob', 'Scrob cu ceapă verde', 'Ouă jumări cu ceapă verde multă, în stil de casă. Gata în câteva minute, cu pâine proaspătă alături.', array['mic_dejun', 'traditionale', 'rapide', 'vegetariene']::text[], 'romaneasca', 2, 5, 10, 'usor', '/retete/ochiuri-romanesti-scrob.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('sarmale', 'Sarmale în foi de varză murată', 'Sarmale moi, cu carne și orez, fierte încet pe pat de varză murată. Se păstrează bine și sunt și mai bune a doua zi.', array['traditionale', 'pranz', 'carne', 'meal_prep']::text[], 'romaneasca', 8, 60, 120, 'dificil', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ardei-umpluti', 'Ardei umpluți', 'Ardei grași umpluți cu carne și orez, fierți în sos de roșii. O mâncare de familie, simplă și sățioasă.', array['traditionale', 'pranz', 'carne']::text[], 'romaneasca', 6, 40, 60, 'mediu', '/retete/ardei-umpluti.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocanita-de-porc', 'Tocăniță de porc', 'Carne de porc înăbușită încet cu ceapă și roșii, până devine fragedă. Merge de minune cu mămăligă.', array['traditionale', 'pranz', 'cina', 'carne', 'meal_prep']::text[], 'romaneasca', 5, 20, 90, 'mediu', '/retete/tocanita-de-porc.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ostropel-de-pui', 'Ostropel de pui', 'Pui fiert în sos de roșii cu mult usturoi, cum se făcea la țară. Se mănâncă cu mămăligă caldă.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 4, 20, 60, 'mediu', '/retete/ostropel-de-pui.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pilaf-de-pui', 'Pilaf de pui', 'Orez fiert în supă împreună cu bucăți de pui rumenit. O mâncare dintr-o singură oală, ușor de făcut.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 4, 15, 40, 'usor', '/retete/pilaf-de-pui.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-fasole-cu-carnati', 'Mâncare de fasole cu cârnați', 'Fasole boabe fiartă încet, cu ceapă și cârnați afumați. O mâncare grea și bună pentru zilele reci.', array['traditionale', 'pranz', 'carne', 'meal_prep']::text[], 'romaneasca', 6, 20, 120, 'mediu', '/retete/mancare-de-fasole-cu-carnati.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ghiveci-de-legume', 'Ghiveci de legume', 'Legume de sezon coapte lent în sos de roșii, la cuptor. Se face ușor și e bun cald sau rece.', array['traditionale', 'pranz', 'cina', 'vegetariene', 'meal_prep']::text[], 'romaneasca', 6, 30, 75, 'usor', '/retete/ghiveci-de-legume.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-de-porc-vita', 'Chiftele', 'Chiftele crocante pe dinafară și fragede înăuntru, din carne de porc și vită. Se servesc cu piure sau salată.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 4, 25, 20, 'usor', '/retete/chiftele-de-porc-vita.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mamaliga-cu-branza-si-smantana', 'Mămăligă cu brânză și smântână', 'Mămăligă caldă, cu brânză sărată și smântână, simplă și potrivită oricând. Merge și ca garnitură.', array['traditionale', 'pranz', 'cina', 'vegetariene']::text[], 'romaneasca', 4, 5, 30, 'usor', '/retete/mamaliga-cu-branza-si-smantana.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tochitura-moldoveneasca', 'Tochitură moldovenească', 'Carne de porc și cârnați într-un sos aromat cu vin, servite cu mămăligă și ou ochi. Tradițională din Moldova.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 4, 20, 60, 'mediu', '/retete/tochitura-moldoveneasca.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('varza-calita-cu-carne', 'Varză călită cu carne de porc', 'Varză albă înăbușită cu carne de porc, ceapă și puțin bulion. O mâncare simplă, bună la prânz.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 5, 25, 70, 'mediu', '/retete/varza-calita-cu-carne.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('musaca-de-cartofi', 'Musaca de cartofi', 'Straturi de cartofi și carne tocată, coapte cu un topping de ou și smântână. Se taie ușor în felii.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 6, 40, 60, 'mediu', '/retete/musaca-de-cartofi.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('friptura-de-porc-la-tava', 'Friptură de porc la tavă', 'Friptură de porc coaptă încet la cuptor, cu cartofi și usturoi. Iese suculentă și frumos rumenită.', array['traditionale', 'pranz', 'carne']::text[], 'romaneasca', 6, 20, 120, 'mediu', '/retete/friptura-de-porc-la-tava.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pui-la-cuptor-cu-cartofi', 'Pulpe de pui la cuptor cu cartofi', 'Pulpe de pui crocante, coapte pe un pat de cartofi cu usturoi și boia. Merge bine pentru o masă în familie.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 4, 15, 60, 'usor', '/retete/pui-la-cuptor-cu-cartofi.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-mazare-cu-pui', 'Mâncare de mazăre cu pui', 'Mazăre verde fiartă ușor cu bucăți de pui, morcov și mărar. O mâncare fragedă, de primăvară.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 4, 15, 45, 'usor', '/retete/mancare-de-mazare-cu-pui.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocana-de-cartofi', 'Tocană de cartofi', 'Cartofi fierți în sos de roșii cu ceapă și boia, la care poți adăuga cârnați. O mâncare caldă, ieftină și bună.', array['traditionale', 'pranz', 'cina', 'vegetariene']::text[], 'romaneasca', 4, 15, 35, 'usor', '/retete/tocana-de-cartofi.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('papricas-de-pui', 'Papricaș de pui', 'Pui fraged într-un sos cremos de boia dulce și smântână. Se servește cu mămăligă sau găluște.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 4, 20, 50, 'mediu', '/retete/papricas-de-pui.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciulama-de-pui-cu-ciuperci', 'Ciulama de pui cu ciuperci', 'Pui și ciuperci într-un sos alb, fin, cu lapte și smântână. Se mănâncă bine cu mămăligă.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 4, 15, 40, 'mediu', '/retete/ciulama-de-pui-cu-ciuperci.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('iahnie-de-fasole', 'Iahnie de fasole', 'Fasole boabe într-un sos gros de ceapă călită, cu boia și dafin. O mâncare de post, sățioasă.', array['traditionale', 'pranz', 'cina', 'vegetariene', 'meal_prep']::text[], 'romaneasca', 6, 20, 100, 'usor', '/retete/iahnie-de-fasole.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mici-la-gratar', 'Mici la grătar cu muștar', 'Mici sfârâitori, făcuți din carne tocată și condimentați cu usturoi și cimbru. Se servesc cu muștar și pâine.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 4, 20, 15, 'mediu', '/retete/mici-la-gratar.webp', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
