  ('chiftele-marinate', 'Chiftele marinate', 'Chiftele prăjite, fierte apoi în sos de roșii cu cimbru și dafin. Bune calde sau reci, cu piure ori cu pâine.', array['traditionale', 'pranz', 'cina', 'carne', 'meal_prep']::text[], 'romaneasca', 6, 25, 40, 'mediu', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ficatei-de-pui-cu-ceapa', 'Ficăței de pui cu ceapă', 'Ficăței rumeniți repede, cu ceapă călită și puțin vin. Ieftini, gata în douăzeci de minute, buni cu mămăligă sau piure.', array['traditionale', 'pranz', 'cina', 'carne', 'rapide']::text[], 'romaneasca', 4, 10, 15, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocanita-de-pui', 'Tocăniță de pui', 'Bucăți de pui înăbușite în sos de ceapă, roșii și ardei, cu usturoi și cimbru. Cel mai bun lângă o mămăligă.', array['traditionale', 'pranz', 'cina', 'carne', 'meal_prep']::text[], 'romaneasca', 4, 15, 45, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('dovlecei-umpluti-cu-carne', 'Dovlecei umpluți cu carne', 'Bărcuțe de dovlecel umplute cu carne tocată și orez, coapte în sos de roșii cu cașcaval deasupra.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 4, 25, 45, 'mediu', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('musaca-de-vinete', 'Musaca de vinete', 'Straturi de vinete rumenite și carne tocată cu roșii, acoperite cu un sos alb și coapte până se rumenesc.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 6, 40, 50, 'mediu', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('piept-de-curcan-cu-legume-la-cuptor', 'Piept de curcan cu legume la tavă', 'Cuburi de curcan coapte în aceeași tavă cu cartofi dulci, ardei, ceapă și dovlecel. O cină ușoară, cu o singură tavă de spălat.', array['pranz', 'cina', 'carne', 'meal_prep']::text[], 'internationala', 4, 15, 35, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('carnati-cu-varza-murata', 'Cârnați cu varză murată la cuptor', 'Varză murată călită cu cimbru și piper, coaptă în tavă cu cârnați afumați deasupra. Mâncarea de iarnă, cu mămăligă.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 4, 15, 60, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('burgeri-de-vita', 'Burgeri de vită de casă', 'Chiftele groase de vită făcute în tigaie, în chiflă cu cașcaval, roșie, salată și ceapă. Mai buni decât la fast-food.', array['pranz', 'cina', 'carne']::text[], 'internationala', 4, 15, 15, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('file-de-merluciu-pane', 'File de merluciu pane', 'Bucăți de pește alb în crustă aurie de pesmet, cu lămâie. Bune cu piure, cu cartofi sau cu salată de varză.', array['peste', 'pranz', 'cina', 'rapide']::text[], 'romaneasca', 4, 10, 15, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('creveti-cu-usturoi', 'Creveți cu usturoi și pătrunjel', 'Creveți săltați în tigaie cu unt, usturoi, puțin ardei iute și lămâie. Gata în zece minute, cu pâine sau paste.', array['peste', 'cina', 'rapide']::text[], 'internationala', 2, 10, 6, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('dorada-la-cuptor', 'Doradă la cuptor cu lămâie și rozmarin', 'Doradă întreagă coaptă pe un pat de cartofi și ceapă, cu lămâie și rozmarin. Arată festiv și se face simplu.', array['peste', 'pranz', 'cina']::text[], 'internationala', 2, 15, 35, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-de-peste', 'Chiftele de pește', 'Chiftele din file de pește alb cu cartof, ceapă și mărar, rumenite în tigaie. Le mănâncă și cine nu prea iubește peștele.', array['peste', 'traditionale', 'pranz', 'cina']::text[], 'romaneasca', 4, 20, 20, 'mediu', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pui-cu-legume-la-wok', 'Pui cu legume la wok', 'Fâșii de pui săltate la foc mare cu ardei, morcov, broccoli și sos de soia cu ghimbir. Cu orez, gata în 25 de minute.', array['pranz', 'cina', 'carne', 'rapide']::text[], 'internationala', 4, 15, 10, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-cartofi-cu-carnati', 'Mâncare de cartofi cu cârnați', 'Cartofi înăbușiți cu ceapă, boia și cârnați afumați, într-un sos gros de roșii. Sățioasă, într-o singură oală.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 4, 15, 35, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-ton-cu-porumb', 'Salată de ton cu porumb și fasole', 'Ton din conservă cu porumb, fasole roșie, ceapă roșie și roșii, cu sos de lămâie. Un prânz rapid, fără gătit.', array['salate', 'peste', 'pranz', 'rapide']::text[], 'internationala', 4, 10, 0, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-sos-de-rosii-si-busuioc', 'Penne cu sos de roșii și busuioc', 'Paste într-un sos simplu de roșii cu usturoi, ulei de măsline și busuioc proaspăt. Gata cât fierb pastele.', array['pranz', 'cina', 'vegetariene', 'rapide']::text[], 'internationala', 4, 5, 20, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-pui-si-broccoli', 'Paste cu pui și broccoli', 'Paste cu fâșii de pui și broccoli, într-un sos cremos cu usturoi și parmezan. Un fel complet, în jumătate de oră.', array['pranz', 'cina', 'carne', 'rapide']::text[], 'internationala', 4, 10, 20, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-ciuperci-si-smantana', 'Paste cu ciuperci și smântână', 'Penne cu ciuperci rumenite, usturoi și smântână, cu pătrunjel. O cină caldă în douăzeci de minute.', array['pranz', 'cina', 'vegetariene', 'rapide']::text[], 'internationala', 4, 10, 15, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-cascaval-la-cuptor', 'Paste cu cașcaval la cuptor', 'Paste într-un sos alb cu mult cașcaval, coapte până se face o crustă aurie. Pe placul copiilor și al celor mari.', array['pranz', 'cina', 'vegetariene']::text[], 'internationala', 6, 15, 30, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-aglio-olio', 'Spaghete cu usturoi, ulei și ardei iute', 'Spaghete aglio e olio: usturoi auriu în ulei de măsline, ardei iute și pătrunjel. Cina din cămară, gata în 15 minute.', array['pranz', 'cina', 'vegetariene', 'rapide']::text[], 'internationala', 4, 5, 12, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('taitei-cu-varza', 'Tăiței cu varză', 'Varză călită încet până se caramelizează, amestecată cu paste și piper. O mâncare simplă, cu ingrediente ieftine.', array['traditionale', 'pranz', 'cina', 'vegetariene']::text[], 'romaneasca', 4, 15, 40, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-paste', 'Salată de paste cu legume', 'Paste reci cu roșii cherry, castravete, porumb, măsline și mozzarella, cu sos de ulei și oțet. Bună la pachet sau la grătar.', array['salate', 'pranz', 'vegetariene', 'meal_prep']::text[], 'internationala', 6, 15, 12, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cuscus-cu-legume', 'Cuscus cu legume coapte', 'Cuscus pufos cu dovlecel, ardei și ceapă coapte, cu lămâie și mentă. Se face aproape singur și e bun și rece.', array['pranz', 'cina', 'vegetariene', 'meal_prep']::text[], 'internationala', 4, 15, 25, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-tabbouleh', 'Salată tabbouleh cu bulgur', 'Salată libaneză cu mult pătrunjel, mentă, roșii și bulgur, cu lămâie și ulei de măsline. Proaspătă și ușoară.', array['salate', 'pranz', 'vegetariene', 'meal_prep']::text[], 'internationala', 4, 20, 10, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-quinoa', 'Salată de quinoa cu legume și feta', 'Quinoa cu castravete, roșii, ardei, ceapă roșie și feta, cu sos de lămâie. Un prânz sățios, bun la pachet.', array['salate', 'pranz', 'vegetariene', 'meal_prep']::text[], 'internationala', 4, 15, 15, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('orez-prajit-cu-ou', 'Orez prăjit cu ou și legume', 'Orez fiert de ieri, sotat la foc mare cu ou, mazăre, morcov și sos de soia. Cel mai bun mod de a folosi resturile.', array['pranz', 'cina', 'vegetariene', 'rapide']::text[], 'internationala', 4, 10, 10, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('wrap-cu-pui-si-legume', 'Lipie cu pui și legume', 'Lipie rulată cu pui rumenit, salată, roșii, castravete și sos de iaurt cu usturoi. Bună la pachet sau pe fugă.', array['pranz', 'cina', 'carne', 'rapide']::text[], 'internationala', 4, 15, 10, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ratatouille', 'Ratatouille', 'Tocană franțuzească din vinete, dovlecei, ardei și roșii, înăbușite cu usturoi și cimbru. Bună caldă, rece sau a doua zi.', array['pranz', 'cina', 'vegetariene', 'meal_prep']::text[], 'internationala', 4, 20, 40, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gnocchi-cu-sos-de-rosii', 'Găluște de cartofi cu sos de roșii', 'Gnocchi făcuți în casă din cartofi și făină, serviți cu sos de roșii și parmezan. Merită efortul o dată, să vezi cât de simplu e.', array['pranz', 'cina', 'vegetariene']::text[], 'internationala', 4, 40, 30, 'mediu', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-minestrone', 'Supă minestrone', 'Supă italiană de legume cu fasole, roșii și paste mici, cu parmezan deasupra. Groasă, colorată și foarte sățioasă.', array['supe_ciorbe', 'pranz', 'vegetariene', 'meal_prep']::text[], 'internationala', 6, 15, 35, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mere-coapte-cu-nuca', 'Mere coapte cu nucă și miere', 'Mere umplute cu nucă, miere și scorțișoară, coapte până se înmoaie. Desertul de toamnă care umple casa de miros.', array['deserturi', 'traditionale', 'vegetariene']::text[], 'romaneasca', 4, 10, 35, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tiramisu', 'Tiramisu', 'Desert italian cu pișcoturi înmuiate în cafea și cremă de mascarpone, presărat cu cacao. Fără coacere, gata peste noapte.', array['deserturi']::text[], 'internationala', 8, 30, 0, 'mediu', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('negresa', 'Negresă', 'Prăjitură pufoasă cu cacao, umedă la mijloc, glazurată cu ciocolată. Cea de la bunica, gata într-o oră.', array['deserturi', 'traditionale']::text[], 'romaneasca', 12, 15, 30, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gogosi', 'Gogoși pufoase', 'Gogoși din aluat dospit, prăjite până se umflă și se rumenesc, cu zahăr pudră. Ca la târg, dar făcute acasă.', array['deserturi', 'traditionale', 'mic_dejun']::text[], 'romaneasca', 8, 20, 30, 'mediu', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pandispan-cu-fructe', 'Pandișpan cu fructe', 'Blat pufos de ouă cu cireșe, vișine sau fructe de pădure coapte în el. Simplu și bun cu fructele de sezon.', array['deserturi', 'traditionale']::text[], 'romaneasca', 10, 15, 35, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('fursecuri-cu-unt', 'Fursecuri cu unt', 'Biscuiți fragezi cu unt și vanilie, pe care îi decupezi în ce forme vrei. Buni la cafea sau ca dar de sărbători.', array['deserturi', 'gustari']::text[], 'romaneasca', 10, 20, 15, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('lapte-de-pasare', 'Lapte de pasăre', 'Cremă de vanilie cu „insulițe” de albuș fierte în lapte. Desertul copilăriei, făcut pe aragaz, fără cuptor.', array['deserturi', 'traditionale']::text[], 'romaneasca', 6, 15, 20, 'mediu', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salam-de-biscuiti', 'Salam de biscuiți', 'Rulou de biscuiți sfărâmați cu cacao, unt, nucă și rahat, întărit la rece. Fără coacere, ca la bunica.', array['deserturi', 'traditionale']::text[], 'romaneasca', 10, 20, 5, 'usor', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cheesecake-fara-coacere', 'Cheesecake fără coacere', 'Blat din biscuiți cu unt și cremă de brânză cu frișcă, cu fructe de pădure deasupra. Se face fără cuptor, cu o zi înainte.', array['deserturi']::text[], 'internationala', 8, 30, 0, 'mediu', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('crema-de-zahar-ars', 'Cremă de zahăr ars', 'Cremă fină de lapte și ouă, coaptă pe caramel, care se răstoarnă cu sosul aurit deasupra. Desertul de duminică.', array['deserturi', 'traditionale']::text[], 'romaneasca', 6, 20, 45, 'mediu', null, '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z')
