insert into public.recipe_steps (id, recipe_id, position, text, created_at, updated_at) values
  ('ciorba-de-perisoare:s1', 'ciorba-de-perisoare', 0, 'Toacă mărunt o ceapă și amestec-o cu carnea tocată, orezul spălat, oul, jumătate din pătrunjelul tocat, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-perisoare:s2', 'ciorba-de-perisoare', 1, 'Pune la fiert 2,5 l de apă cu sare. Adaugă ceapa rămasă, morcovii, ardeiul, țelina și păstârnacul tăiate cubulețe și fierbe 15 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-perisoare:s3', 'ciorba-de-perisoare', 2, 'Cu mâinile ude, formează perișoare cât o nucă și pune-le pe rând în ciorba care clocotește.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-perisoare:s4', 'ciorba-de-perisoare', 3, 'Fierbe la foc mic 25–30 de minute, până se înmoaie orezul din perișoare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-perisoare:s5', 'ciorba-de-perisoare', 4, 'Adaugă bulionul și borșul fiert separat, apoi mai fierbe 5 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-perisoare:s6', 'ciorba-de-perisoare', 5, 'Stinge focul, potrivește de sare și presară leușteanul și restul de verdeață tocată.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-legume:s1', 'ciorba-de-legume', 0, 'Curăță legumele și taie-le cubulețe: ceapa, morcovii, păstârnacul, țelina, ardeiul, cartofii, dovleceii și fasolea verde.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-legume:s2', 'ciorba-de-legume', 1, 'Încălzește uleiul într-o oală și călește ceapa, morcovii, păstârnacul și țelina 5 minute, amestecând.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-legume:s3', 'ciorba-de-legume', 2, 'Adaugă 2,5 l de apă caldă, ardeiul, cartofii și fasolea verde. Fierbe la foc mediu 15 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-legume:s4', 'ciorba-de-legume', 3, 'Pune dovleceii și roșiile tăiate cubulețe și mai fierbe 10 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-legume:s5', 'ciorba-de-legume', 4, 'Toarnă borșul, sare și piper după gust și lasă să dea în clocot 5 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-legume:s6', 'ciorba-de-legume', 5, 'Stinge focul, adaugă leușteanul și pătrunjelul tocate și servește cu smântână, dacă vrei.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-pui:s1', 'ciorba-de-pui', 0, 'Pune pulpele de pui în oală cu 2,5 l de apă rece și sare. Fierbe la foc mic 30 de minute, spumând din când în când.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-pui:s2', 'ciorba-de-pui', 1, 'Adaugă ceapa întreagă, morcovii și țelina tăiate bucăți și mai fierbe 15 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-pui:s3', 'ciorba-de-pui', 2, 'Scoate pulpele și legumele. Desprinde carnea de pe os și taie-o bucățele.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-pui:s4', 'ciorba-de-pui', 3, 'Pune orezul spălat în supă și fierbe 15 minute, până se înmoaie. Pune carnea înapoi în oală.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-pui:s5', 'ciorba-de-pui', 4, 'Bate gălbenușurile cu sucul de lămâie, adaugă 2 polonice de supă fierbinte, amestecând continuu, apoi toarnă totul în oală.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-pui:s6', 'ciorba-de-pui', 5, 'Nu mai fierbe supa. Adaugă piper și pătrunjelul tocat și servește imediat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-pui-cu-taitei:s1', 'supa-de-pui-cu-taitei', 0, 'Pune carnea de pui în oală cu 3 l de apă rece și sare. Adu la fierbere și dă la o parte spuma.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-pui-cu-taitei:s2', 'supa-de-pui-cu-taitei', 1, 'Adaugă ceapa întreagă, morcovii, rădăcina de pătrunjel și țelina. Fierbe la foc mic 50 de minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-pui-cu-taitei:s3', 'supa-de-pui-cu-taitei', 2, 'Scoate carnea și legumele. Desprinde carnea de pe os și taie-o bucățele; taie morcovii rondele.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-pui-cu-taitei:s4', 'supa-de-pui-cu-taitei', 3, 'Strecoară supa, pune-o înapoi pe foc și adu-o la fierbere.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-pui-cu-taitei:s5', 'supa-de-pui-cu-taitei', 4, 'Adaugă tăițeii și fierbe 5 minute, sau cât scrie pe pachet.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-pui-cu-taitei:s6', 'supa-de-pui-cu-taitei', 5, 'Pune înapoi carnea și morcovii, potrivește de sare și piper și presară pătrunjel tocat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-fasole-cu-afumatura:s1', 'ciorba-de-fasole-cu-afumatura', 0, 'Scurge fasolea înmuiată, pune-o în oală cu apă rece și fierbe 10 minute. Aruncă apa și acoperă cu 3 l de apă proaspătă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-fasole-cu-afumatura:s2', 'ciorba-de-fasole-cu-afumatura', 1, 'Adaugă costița afumată tăiată bucăți și foile de dafin. Fierbe la foc mic 60 de minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-fasole-cu-afumatura:s3', 'ciorba-de-fasole-cu-afumatura', 2, 'Între timp, călește ceapa tocată, morcovii rași și țelina cubulețe în ulei, 8 minute. Adaugă bulionul și boiaua și mai ține pe foc 2 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-fasole-cu-afumatura:s4', 'ciorba-de-fasole-cu-afumatura', 3, 'Pune prăjeala în oală, adaugă ardeiul tăiat cubulețe și fierbe încă 30 de minute, până fasolea se înmoaie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-fasole-cu-afumatura:s5', 'ciorba-de-fasole-cu-afumatura', 4, 'Toarnă borșul și fierbe 10 minute. Potrivește de sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-fasole-cu-afumatura:s6', 'ciorba-de-fasole-cu-afumatura', 5, 'Presară leuștean tocat și servește cu ardei iute, dacă îți place.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-vacuta:s1', 'ciorba-de-vacuta', 0, 'Pune carnea de vită în oală cu 3 l de apă rece și sare. Adu la fierbere și dă spuma la o parte.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-vacuta:s2', 'ciorba-de-vacuta', 1, 'Fierbe la foc mic 60 de minute, apoi adaugă ceapa, morcovii, păstârnacul și țelina tăiate cubulețe.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-vacuta:s3', 'ciorba-de-vacuta', 2, 'După 15 minute pune ardeiul și cartofii tăiați cubulețe și fierbe încă 15 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-vacuta:s4', 'ciorba-de-vacuta', 3, 'Adaugă bulionul și borșul. Mai fierbe 10 minute, până carnea e fragedă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-vacuta:s5', 'ciorba-de-vacuta', 4, 'Scoate carnea, taie-o în bucăți și pune-o înapoi în oală. Potrivește de sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-vacuta:s6', 'ciorba-de-vacuta', 5, 'Presară verdeața tocată și servește cu smântână, dacă vrei.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-loboda:s1', 'ciorba-de-loboda', 0, 'Spală loboda de mai multe ori și toac-o grosier.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-loboda:s2', 'ciorba-de-loboda', 1, 'Încălzește uleiul și călește ceapa tocată și morcovul ras 5 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-loboda:s3', 'ciorba-de-loboda', 2, 'Adaugă 2,5 l de apă caldă, cartofii cubulețe și orezul spălat. Fierbe 15 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-loboda:s4', 'ciorba-de-loboda', 3, 'Pune loboda și fierbe încă 8 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-loboda:s5', 'ciorba-de-loboda', 4, 'Toarnă borșul, adaugă usturoiul pisat, sare și piper și dă un clocot.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-loboda:s6', 'ciorba-de-loboda', 5, 'Presară mărar și pătrunjel tocate. Servește cu smântână, dacă îți place.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-dovleac:s1', 'supa-crema-de-dovleac', 0, 'Curăță dovleacul, ceapa, morcovii și cartoful și taie-le cuburi mici.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-dovleac:s2', 'supa-crema-de-dovleac', 1, 'Topește untul într-o oală și călește ceapa și usturoiul 3 minute, fără să se rumenească.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-dovleac:s3', 'supa-crema-de-dovleac', 2, 'Adaugă restul legumelor și 1,2 l de apă fierbinte. Fierbe la foc mediu 20–25 de minute, până se înmoaie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-dovleac:s4', 'supa-crema-de-dovleac', 3, 'Mixează supa cu un blender vertical până devine fină.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-dovleac:s5', 'supa-crema-de-dovleac', 4, 'Adaugă smântâna, sare, piper și puțină nucșoară și mai încălzește 2 minute, fără să fiarbă tare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-dovleac:s6', 'supa-crema-de-dovleac', 5, 'Servește cu semințe de dovleac presărate deasupra.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-legume:s1', 'supa-crema-de-legume', 0, 'Taie ceapa, morcovii, cartofii și dovleceii cuburi, iar broccoli buchețele.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-legume:s2', 'supa-crema-de-legume', 1, 'Încălzește uleiul într-o oală și călește ceapa și usturoiul 3 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-legume:s3', 'supa-crema-de-legume', 2, 'Adaugă morcovii și cartofii, acoperă cu 1,2 l de apă fierbinte și fierbe 10 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-legume:s4', 'supa-crema-de-legume', 3, 'Pune dovleceii și broccoli și fierbe încă 10 minute, până toate legumele sunt moi.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-legume:s5', 'supa-crema-de-legume', 4, 'Mixează cu blenderul vertical până ai o cremă fină. Adaugă smântana, dacă folosești, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-legume:s6', 'supa-crema-de-legume', 5, 'Mai încălzește 2 minute și servește cu pătrunjel tocat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-rosii:s1', 'supa-de-rosii', 0, 'Taie roșiile bucăți, iar ceapa, morcovul și usturoiul mărunt.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-rosii:s2', 'supa-de-rosii', 1, 'Încălzește uleiul într-o oală și călește ceapa, morcovul și usturoiul 5 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-rosii:s3', 'supa-de-rosii', 2, 'Adaugă roșiile, zahărul și 500 ml de apă. Fierbe la foc mic 20 de minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-rosii:s4', 'supa-de-rosii', 3, 'Mixează supa cu blenderul vertical și treci-o printr-o strecurătoare, dacă vrei să scapi de coji.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-rosii:s5', 'supa-de-rosii', 4, 'Potrivește de sare și piper și mai încălzește 3 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-rosii:s6', 'supa-de-rosii', 5, 'Servește cu busuioc rupt deasupra și puțină smântână.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bors-de-peste:s1', 'bors-de-peste', 0, 'Toacă ceapa, morcovii, păstârnacul, țelina și ardeiul. Pune-le într-o oală cu 3 l de apă și sare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bors-de-peste:s2', 'bors-de-peste', 1, 'Fierbe legumele la foc mediu 20 de minute, până se înmoaie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bors-de-peste:s3', 'bors-de-peste', 2, 'Adaugă roșiile tăiate bucăți și boabele de piper și mai fierbe 5 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bors-de-peste:s4', 'bors-de-peste', 3, 'Pune bucățile de pește în oală, cu grijă, și fierbe la foc mic 15–20 de minute, fără să amesteci prea mult.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bors-de-peste:s5', 'bors-de-peste', 4, 'Toarnă borșul, dă un clocot și potrivește de sare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bors-de-peste:s6', 'bors-de-peste', 5, 'Stinge focul, presară leuștean și pătrunjel tocate și servește cu ardei iute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-galuste:s1', 'supa-de-galuste', 0, 'Pune puiul în oală cu 3 l de apă rece și sare. Adu la fierbere, dă spuma la o parte și adaugă ceapa, morcovii, rădăcina de pătrunjel și țelina.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-galuste:s2', 'supa-de-galuste', 1, 'Fierbe la foc mic 50 de minute, apoi scoate carnea și legumele. Strecoară supa.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-galuste:s3', 'supa-de-galuste', 2, 'Bate ouăle cu un praf de sare, adaugă untul topit și grisul și amestecă. Lasă compoziția 10 minute să se umfle.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-galuste:s4', 'supa-de-galuste', 3, 'Adu supa la clocot. Cu două linguri ude, formează găluște și pune-le pe rând în supă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-galuste:s5', 'supa-de-galuste', 4, 'Fierbe 12–15 minute la foc mic, acoperit, până găluștele plutesc și cresc.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-galuste:s6', 'supa-de-galuste', 5, 'Pune carnea desfăcută și morcovii tăiați rondele în supă, adaugă pătrunjel tocat și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-taraneasca-de-porc:s1', 'ciorba-taraneasca-de-porc', 0, 'Pune carnea de porc în oală cu 3 l de apă rece și sare. Adu la fierbere și dă spuma la o parte.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-taraneasca-de-porc:s2', 'ciorba-taraneasca-de-porc', 1, 'Adaugă ceapa, morcovii, țelina și păstârnacul tăiate cubulețe. Fierbe la foc mic 40 de minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-taraneasca-de-porc:s3', 'ciorba-taraneasca-de-porc', 2, 'Pune ardeiul și cartofii tăiați cubulețe și mai fierbe 15 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-taraneasca-de-porc:s4', 'ciorba-taraneasca-de-porc', 3, 'Adaugă bulionul și borșul și fierbe încă 10 minute, până carnea e fragedă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-taraneasca-de-porc:s5', 'ciorba-taraneasca-de-porc', 4, 'Pune usturoiul pisat, sare și piper și dă un clocot.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-taraneasca-de-porc:s6', 'ciorba-taraneasca-de-porc', 5, 'Presară leuștean și pătrunjel tocate și servește cu ardei iute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('omleta-cu-legume:s1', 'omleta-cu-legume', 0, 'Taie ardeiul, roșia și ciupercile cubulețe, iar ceapa verde felii subțiri.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('omleta-cu-legume:s2', 'omleta-cu-legume', 1, 'Încălzește uleiul într-o tigaie și călește ardeiul și ciupercile 3–4 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('omleta-cu-legume:s3', 'omleta-cu-legume', 2, 'Adaugă roșia și ceapa verde și mai ține pe foc 1 minut.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('omleta-cu-legume:s4', 'omleta-cu-legume', 3, 'Bate ouăle cu sare și piper și toarnă-le peste legume.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('omleta-cu-legume:s5', 'omleta-cu-legume', 4, 'Gătește la foc mic, acoperit, 3–4 minute, până se prinde omleta. Presară cașcavalul, dacă folosești.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('omleta-cu-legume:s6', 'omleta-cu-legume', 5, 'Îndoaie omleta în două și servește cu pătrunjel tocat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('oua-ochiuri:s1', 'oua-ochiuri', 0, 'Prăjește feliile de pâine în toaster sau într-o tigaie uscată, până se rumenesc.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('oua-ochiuri:s2', 'oua-ochiuri', 1, 'Topește untul într-o tigaie la foc mediu.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('oua-ochiuri:s3', 'oua-ochiuri', 2, 'Sparge ouăle în tigaie, cu grijă să nu se rupă gălbenușurile.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('oua-ochiuri:s4', 'oua-ochiuri', 3, 'Presară sare și piper și gătește 3–4 minute, până se albește albușul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('oua-ochiuri:s5', 'oua-ochiuri', 4, 'Pune ouăle peste pâinea prăjită și servește cu felii de roșie și pătrunjel.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-oua:s1', 'salata-de-oua', 0, 'Pune ouăle în apă clocotită și fierbe-le 10 minute. Răcește-le în apă rece și curăță-le.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-oua:s2', 'salata-de-oua', 1, 'Taie ouăle mărunt cu cuțitul sau cu furculița.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-oua:s3', 'salata-de-oua', 2, 'Toacă ceapa verde și castraveții murați, dacă îi folosești.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-oua:s4', 'salata-de-oua', 3, 'Amestecă ouăle cu iaurtul, muștarul, ceapa verde, castraveții și mărarul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-oua:s5', 'salata-de-oua', 4, 'Potrivește de sare și piper și servește pe felii de pâine sau cu legume proaspete.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('terci-de-ovaz-cu-fructe:s1', 'terci-de-ovaz-cu-fructe', 0, 'Pune fulgii de ovăz și laptele într-o oală mică.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('terci-de-ovaz-cu-fructe:s2', 'terci-de-ovaz-cu-fructe', 1, 'Încălzește la foc mic 6–8 minute, amestecând des, până se îngroașă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('terci-de-ovaz-cu-fructe:s3', 'terci-de-ovaz-cu-fructe', 2, 'Taie banana rondele și mărul cubulețe.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('terci-de-ovaz-cu-fructe:s4', 'terci-de-ovaz-cu-fructe', 3, 'Împarte terciul în două boluri și pune fructele deasupra.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('terci-de-ovaz-cu-fructe:s5', 'terci-de-ovaz-cu-fructe', 4, 'Adaugă mierea, puțină scorțișoară și nucile sparte, dacă vrei.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('clatite:s1', 'clatite', 0, 'Bate ouăle cu zahărul și un praf de sare. Adaugă jumătate din lapte.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('clatite:s2', 'clatite', 1, 'Încorporează făina treptat, amestecând ca să nu rămână cocoloașe. Adaugă restul laptelui și o lingură de ulei.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('clatite:s3', 'clatite', 2, 'Lasă aluatul 15 minute să se odihnească.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('clatite:s4', 'clatite', 3, 'Încinge o tigaie unsă ușor cu ulei. Toarnă un polonic mic de aluat și întinde-l în strat subțire.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('clatite:s5', 'clatite', 4, 'Coace 1–2 minute pe o parte, până se rumenește, apoi întoarce clătita și mai coace 1 minut.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('clatite:s6', 'clatite', 5, 'Umple cu dulceață sau cu ce îți place și rulează clătitele.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('sandvis-cu-branza-si-legume:s1', 'sandvis-cu-branza-si-legume', 0, 'Prăjește ușor feliile de pâine, dacă vrei să fie crocante.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('sandvis-cu-branza-si-legume:s2', 'sandvis-cu-branza-si-legume', 1, 'Întinde crema de brânză pe toate feliile.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('sandvis-cu-branza-si-legume:s3', 'sandvis-cu-branza-si-legume', 2, 'Taie castravetele, roșia și ardeiul în felii subțiri.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('sandvis-cu-branza-si-legume:s4', 'sandvis-cu-branza-si-legume', 3, 'Așază pe două felii frunzele de salată, castravetele, roșia și ardeiul. Adaugă sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('sandvis-cu-branza-si-legume:s5', 'sandvis-cu-branza-si-legume', 4, 'Acoperă cu celelalte felii, taie sandvișurile în două și servește.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bulz:s1', 'bulz', 0, 'Fierbe 1,2 l de apă cu sare. Toarnă malaiul în ploaie, amestecând continuu, și fierbe 25 de minute la foc mic, până se desprinde de oală.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bulz:s2', 'bulz', 1, 'Încălzește cuptorul la 200°C.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bulz:s3', 'bulz', 2, 'Cu mâinile ude, formează patru bulgări de mămăligă și fă câte o adâncitură în fiecare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bulz:s4', 'bulz', 3, 'Umple adânciturile cu brânză de burduf și telemea sfărâmată și închide bulgării.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bulz:s5', 'bulz', 4, 'Pune-i pe o tavă unsă cu unt și coace 15 minute, până se rumenesc și brânza se topește.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bulz:s6', 'bulz', 5, 'Servește fierbinte, cu smântână.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gris-cu-lapte:s1', 'gris-cu-lapte', 0, 'Pune laptele cu zahărul la încălzit într-o oală mică, la foc mediu.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gris-cu-lapte:s2', 'gris-cu-lapte', 1, 'Când laptele începe să fiarbă, adaugă grisul în ploaie, amestecând continuu cu un tel.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gris-cu-lapte:s3', 'gris-cu-lapte', 2, 'Fierbe la foc mic 4–5 minute, mereu amestecând, până se îngroașă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gris-cu-lapte:s4', 'gris-cu-lapte', 3, 'Adaugă untul, dacă îl folosești, și stinge focul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gris-cu-lapte:s5', 'gris-cu-lapte', 4, 'Servește cald, cu scorțișoară sau dulceață deasupra.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('iaurt-cu-musli-si-fructe:s1', 'iaurt-cu-musli-si-fructe', 0, 'Taie banana rondele și mărul cubulețe.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('iaurt-cu-musli-si-fructe:s2', 'iaurt-cu-musli-si-fructe', 1, 'Pune iaurtul în două boluri.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('iaurt-cu-musli-si-fructe:s3', 'iaurt-cu-musli-si-fructe', 2, 'Adaugă fructele deasupra.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('iaurt-cu-musli-si-fructe:s4', 'iaurt-cu-musli-si-fructe', 3, 'Presară muslile chiar înainte de servire, ca să rămână crocante.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('iaurt-cu-musli-si-fructe:s5', 'iaurt-cu-musli-si-fructe', 4, 'Dacă vrei mai dulce, adaugă puțină miere.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ochiuri-romanesti-scrob:s1', 'ochiuri-romanesti-scrob', 0, 'Spală și toacă ceapa verde, cu tot cu părțile verzi.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ochiuri-romanesti-scrob:s2', 'ochiuri-romanesti-scrob', 1, 'Topește untul într-o tigaie și călește ceapa 2–3 minute, la foc mic.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ochiuri-romanesti-scrob:s3', 'ochiuri-romanesti-scrob', 2, 'Bate ouăle cu sare și piper și toarnă-le peste ceapă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ochiuri-romanesti-scrob:s4', 'ochiuri-romanesti-scrob', 3, 'Amestecă încet, 2–3 minute, până se închag, dar rămân moi și cremoase.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ochiuri-romanesti-scrob:s5', 'ochiuri-romanesti-scrob', 4, 'Presară telemeaua, dacă folosești, și servește imediat cu pâine.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('sarmale:s1', 'sarmale', 0, 'Toacă ceapa mărunt și călește-o în ulei 5 minute, cu boiaua la final. Lasă-o să se răcească.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('sarmale:s2', 'sarmale', 1, 'Amestecă ceapa cu carnea tocată, orezul spălat, jumătate din verdeața tocată, cimbrul, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('sarmale:s3', 'sarmale', 2, 'Pune pe fiecare foaie de varză câte o lingură de umplutură și rulează strâns, îndoind marginile spre interior.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('sarmale:s4', 'sarmale', 3, 'Așază în oală varza tocată, apoi sarmalele în straturi, cu dafinul și restul verdeței între ele.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('sarmale:s5', 'sarmale', 4, 'Amestecă bulionul cu 500 ml de apă, toarnă peste sarmale până le acoperă și pune deasupra câteva foi de varză.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('sarmale:s6', 'sarmale', 5, 'Fierbe la foc mic, cu capacul pus, 2 ore, până se înmoaie varza și orezul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('sarmale:s7', 'sarmale', 6, 'Lasă-le 15 minute în oală după ce stingi focul. Servește cu smântână, dacă vrei.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ardei-umpluti:s1', 'ardei-umpluti', 0, 'Spală ardeii, taie-le capacele și scoate cotoarele și semințele. Păstrează capacele.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ardei-umpluti:s2', 'ardei-umpluti', 1, 'Călește o ceapă tocată și morcovul ras în 30 ml de ulei, 5 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ardei-umpluti:s3', 'ardei-umpluti', 2, 'Amestecă legumele răcite cu carnea, orezul spălat, jumătate din verdeață, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ardei-umpluti:s4', 'ardei-umpluti', 3, 'Umple ardeii cu compoziția, fără să îi îndesești prea tare, și pune-le capacele.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ardei-umpluti:s5', 'ardei-umpluti', 4, 'Așază ardeii în oală, adaugă dafinul și ceapa rămasă tăiată felii, apoi toarnă bulionul diluat cu 500 ml de apă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ardei-umpluti:s6', 'ardei-umpluti', 5, 'Fierbe la foc mic, cu capacul pus, 60 de minute, până se înmoaie ardeii și orezul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ardei-umpluti:s7', 'ardei-umpluti', 6, 'Presară verdeața rămasă și servește cu smântână.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocanita-de-porc:s1', 'tocanita-de-porc', 0, 'Încinge uleiul într-o oală cu fundul gros și rumenește carnea 10 minute, pe porții, la foc potrivit.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocanita-de-porc:s2', 'tocanita-de-porc', 1, 'Adaugă ceapa tăiată mărunt și călește 5 minute, până devine sticloasă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocanita-de-porc:s3', 'tocanita-de-porc', 2, 'Pune pasta de tomate, boiaua, dafinul, cimbrul, sare și piper. Amestecă 1 minut.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocanita-de-porc:s4', 'tocanita-de-porc', 3, 'Toarnă 300 ml de apă caldă, acoperă și fierbe la foc mic 60–70 de minute, amestecând din când în când.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocanita-de-porc:s5', 'tocanita-de-porc', 4, 'Adaugă usturoiul pisat și mai lasă 10 minute, până se leagă sosul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocanita-de-porc:s6', 'tocanita-de-porc', 5, 'Presară pătrunjel tocat și servește fierbinte, cu mămăligă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ostropel-de-pui:s1', 'ostropel-de-pui', 0, 'Condimentează bucățile de pui cu sare și piper și rumenește-le în ulei încins, 4–5 minute pe fiecare parte.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ostropel-de-pui:s2', 'ostropel-de-pui', 1, 'Scoate puiul și, în aceeași oală, călește ceapa tăiată mărunt 5 minute, apoi adaugă boiaua.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ostropel-de-pui:s3', 'ostropel-de-pui', 2, 'Pune la loc puiul, adaugă bulionul, dafinul și 200 ml de apă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ostropel-de-pui:s4', 'ostropel-de-pui', 3, 'Acoperă și fierbe la foc mic 35–40 de minute, până se desprinde carnea de pe os.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ostropel-de-pui:s5', 'ostropel-de-pui', 4, 'Adaugă usturoiul pisat și mai fierbe 5 minute, fără capac, ca sosul să se îngroașe.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ostropel-de-pui:s6', 'ostropel-de-pui', 5, 'Presară pătrunjel tocat și servește cu mămăligă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pilaf-de-pui:s1', 'pilaf-de-pui', 0, 'Rumenește puiul în ulei 6–7 minute, cu sare și piper, apoi scoate-l din oală.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pilaf-de-pui:s2', 'pilaf-de-pui', 1, 'În același ulei călește ceapa tocată, morcovul ras și ardeiul tăiat cubulețe, 5 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pilaf-de-pui:s3', 'pilaf-de-pui', 2, 'Adaugă orezul spălat și amestecă 2 minute, până devine ușor sticlos.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pilaf-de-pui:s4', 'pilaf-de-pui', 3, 'Pune boiaua și puiul la loc, apoi toarnă 600 ml de apă fierbinte în care ai dizolvat cubul de supă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pilaf-de-pui:s5', 'pilaf-de-pui', 4, 'Acoperă și fierbe la foc mic 18–20 de minute, fără să amesteci, până se absoarbe tot lichidul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pilaf-de-pui:s6', 'pilaf-de-pui', 5, 'Lasă 5 minute acoperit, afânează cu furculița și presară pătrunjel tocat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-fasole-cu-carnati:s1', 'mancare-de-fasole-cu-carnati', 0, 'Scurge fasolea înmuiată, pune-o la fiert în apă rece și lasă-o 10 minute. Aruncă apa și acoperă din nou cu apă fierbinte.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-fasole-cu-carnati:s2', 'mancare-de-fasole-cu-carnati', 1, 'Fierbe fasolea la foc mic cu morcovul întreg și dafinul, 60–75 de minute, până se înmoaie. Sărează abia spre final.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-fasole-cu-carnati:s3', 'mancare-de-fasole-cu-carnati', 2, 'Într-o tigaie, călește ceapa tocată în ulei 5 minute, apoi adaugă cârnații și rumenește-i 5 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-fasole-cu-carnati:s4', 'mancare-de-fasole-cu-carnati', 3, 'Pune în tigaie pasta de tomate, boiaua și cimbrul, amestecă 1 minut și toarnă totul peste fasole.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-fasole-cu-carnati:s5', 'mancare-de-fasole-cu-carnati', 4, 'Fierbe împreună 25–30 de minute, până se leagă sosul. Adaugă usturoiul pisat și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-fasole-cu-carnati:s6', 'mancare-de-fasole-cu-carnati', 5, 'Presară pătrunjel tocat și servește cu murături.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ghiveci-de-legume:s1', 'ghiveci-de-legume', 0, 'Încălzește cuptorul la 190 °C.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ghiveci-de-legume:s2', 'ghiveci-de-legume', 1, 'Curăță legumele și taie-le cuburi de aproximativ 3 cm. Pune vinetele la scurs cu puțină sare 10 minute, apoi clătește-le.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ghiveci-de-legume:s3', 'ghiveci-de-legume', 2, 'Amestecă toate legumele într-o tavă adâncă cu uleiul, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ghiveci-de-legume:s4', 'ghiveci-de-legume', 3, 'Dizolvă bulionul în 200 ml de apă și toarnă peste legume. Adaugă usturoiul tăiat felii.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ghiveci-de-legume:s5', 'ghiveci-de-legume', 4, 'Acoperă tava cu folie și coace 45 de minute. Scoate folia și mai coace 30 de minute, amestecând o dată.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ghiveci-de-legume:s6', 'ghiveci-de-legume', 5, 'Presară pătrunjel tocat și servește cald sau rece.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-de-porc-vita:s1', 'chiftele-de-porc-vita', 0, 'Înmoaie feliile de pâine în lapte 5 minute, apoi stoarce-le bine.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-de-porc-vita:s2', 'chiftele-de-porc-vita', 1, 'Amestecă într-un bol carnea, pâinea, ceapa rasă, usturoiul pisat, oul, pătrunjelul tocat, sare și piper, până se leagă compoziția.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-de-porc-vita:s3', 'chiftele-de-porc-vita', 2, 'Lasă amestecul 15 minute la rece, apoi formează bile turtite cât palma ta de mică.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-de-porc-vita:s4', 'chiftele-de-porc-vita', 3, 'Tăvălește chiftelele prin făină.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-de-porc-vita:s5', 'chiftele-de-porc-vita', 4, 'Prăjește-le în ulei încins la foc mediu, 4–5 minute pe fiecare parte, până se rumenesc și sunt coapte pe dinăuntru.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-de-porc-vita:s6', 'chiftele-de-porc-vita', 5, 'Scurge-le pe hârtie de bucătărie și servește calde.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mamaliga-cu-branza-si-smantana:s1', 'mamaliga-cu-branza-si-smantana', 0, 'Fierbe 1,2 l de apă cu puțină sare într-o oală cu fundul gros.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mamaliga-cu-branza-si-smantana:s2', 'mamaliga-cu-branza-si-smantana', 1, 'Toarnă mălaiul în ploaie, amestecând continuu cu un tel sau cu lingura de lemn, ca să nu se facă cocoloașe.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mamaliga-cu-branza-si-smantana:s3', 'mamaliga-cu-branza-si-smantana', 2, 'Fierbe la foc mic 20–25 de minute, amestecând des, până se desprinde de pe pereții oalei.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mamaliga-cu-branza-si-smantana:s4', 'mamaliga-cu-branza-si-smantana', 3, 'Adaugă untul, dacă folosești, și amestecă încă 1 minut.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mamaliga-cu-branza-si-smantana:s5', 'mamaliga-cu-branza-si-smantana', 4, 'Răstoarnă mămăliga pe un fund de lemn sau în farfurii și taie-o felii.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mamaliga-cu-branza-si-smantana:s6', 'mamaliga-cu-branza-si-smantana', 5, 'Servește caldă, cu brânză și smântână deasupra.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tochitura-moldoveneasca:s1', 'tochitura-moldoveneasca', 0, 'Rumenește carnea de porc în ulei 10 minute, la foc mare, amestecând des.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tochitura-moldoveneasca:s2', 'tochitura-moldoveneasca', 1, 'Adaugă ceapa tăiată mărunt și cârnații și călește încă 8 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tochitura-moldoveneasca:s3', 'tochitura-moldoveneasca', 2, 'Pune pasta de tomate, dafinul, sare și piper, apoi toarnă vinul și lasă-l să scadă 2 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tochitura-moldoveneasca:s4', 'tochitura-moldoveneasca', 3, 'Adaugă 200 ml de apă, acoperă și fierbe la foc mic 35–40 de minute, până se înmoaie carnea.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tochitura-moldoveneasca:s5', 'tochitura-moldoveneasca', 4, 'Pune usturoiul pisat în ultimele 5 minute. Între timp, fă mămăliga și prăjește ouăle ochiuri.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tochitura-moldoveneasca:s6', 'tochitura-moldoveneasca', 5, 'Servește tochitura peste mămăligă, cu ou ochi deasupra și cu brânză, dacă vrei.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('varza-calita-cu-carne:s1', 'varza-calita-cu-carne', 0, 'Rumenește carnea în jumătate din ulei, 10 minute, apoi adaugă ceapa tocată și călește 5 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('varza-calita-cu-carne:s2', 'varza-calita-cu-carne', 1, 'Toarnă 150 ml de apă, acoperă și fierbe 25 de minute la foc mic.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('varza-calita-cu-carne:s3', 'varza-calita-cu-carne', 2, 'Între timp, în altă oală, călește varza în uleiul rămas 10 minute, cu sare, amestecând des.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('varza-calita-cu-carne:s4', 'varza-calita-cu-carne', 3, 'Adaugă peste varză carnea cu sosul ei, pasta de tomate, boiaua, dafinul, chimenul și piperul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('varza-calita-cu-carne:s5', 'varza-calita-cu-carne', 4, 'Acoperă și fierbe la foc mic 25–30 de minute, până se înmoaie varza. Dacă se usucă, adaugă puțină apă caldă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('varza-calita-cu-carne:s6', 'varza-calita-cu-carne', 5, 'Presară mărar tocat, dacă folosești, și servește caldă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('musaca-de-cartofi:s1', 'musaca-de-cartofi', 0, 'Încălzește cuptorul la 200 °C. Curăță cartofii și taie-i rondele subțiri. Fierbe-i 5 minute în apă cu sare și scurge-i.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('musaca-de-cartofi:s2', 'musaca-de-cartofi', 1, 'Călește ceapa tocată în ulei 5 minute, apoi adaugă carnea și gătește 12 minute, mărunțind-o cu lingura.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('musaca-de-cartofi:s3', 'musaca-de-cartofi', 2, 'Adaugă pasta de tomate, pătrunjelul tocat, sare și piper și mai gătește 3 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('musaca-de-cartofi:s4', 'musaca-de-cartofi', 3, 'Unge o tavă cu ulei. Pune jumătate din cartofi, apoi carnea, apoi restul de cartofi.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('musaca-de-cartofi:s5', 'musaca-de-cartofi', 4, 'Bate ouăle cu smântâna și puțină sare și toarnă peste musaca.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('musaca-de-cartofi:s6', 'musaca-de-cartofi', 5, 'Coace 35–40 de minute, până se rumenește deasupra. Lasă 10 minute să se odihnească înainte de tăiat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('friptura-de-porc-la-tava:s1', 'friptura-de-porc-la-tava', 0, 'Încălzește cuptorul la 200 °C.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('friptura-de-porc-la-tava:s2', 'friptura-de-porc-la-tava', 1, 'Freacă carnea cu sare, piper, boia, cimbru și jumătate din usturoiul pisat. Las-o 20 de minute la temperatura camerei.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('friptura-de-porc-la-tava:s3', 'friptura-de-porc-la-tava', 2, 'Pune carnea într-o tavă, cu ceapa tăiată felii groase, dafinul și uleiul. Toarnă 200 ml de apă pe fundul tăvii.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('friptura-de-porc-la-tava:s4', 'friptura-de-porc-la-tava', 3, 'Coace 30 de minute la 200 °C, apoi acoperă cu folie și coboară la 170 °C. Mai coace 60 de minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('friptura-de-porc-la-tava:s5', 'friptura-de-porc-la-tava', 4, 'Adaugă cartofii curățați, tăiați felii groase, cu sare și restul de usturoi. Coace încă 30 de minute fără folie, până se rumenesc.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('friptura-de-porc-la-tava:s6', 'friptura-de-porc-la-tava', 5, 'Lasă carnea 10 minute să se odihnească, apoi taie-o felii și servește cu cartofii și sosul din tavă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pui-la-cuptor-cu-cartofi:s1', 'pui-la-cuptor-cu-cartofi', 0, 'Încălzește cuptorul la 200 °C.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pui-la-cuptor-cu-cartofi:s2', 'pui-la-cuptor-cu-cartofi', 1, 'Amestecă într-un castron uleiul, boiaua, cimbrul, usturoiul pisat, sare și piper. Unge pulpele cu amestecul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pui-la-cuptor-cu-cartofi:s3', 'pui-la-cuptor-cu-cartofi', 2, 'Curăță cartofii și taie-i felii groase. Taie ceapa felii și amestec-o cu cartofii, puțin ulei, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pui-la-cuptor-cu-cartofi:s4', 'pui-la-cuptor-cu-cartofi', 3, 'Pune cartofii în tavă și așază pulpele deasupra, cu pielea în sus.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pui-la-cuptor-cu-cartofi:s5', 'pui-la-cuptor-cu-cartofi', 4, 'Coace 55–60 de minute, întorcând cartofii o dată la jumătate, până se rumenesc pulpele și carnea e gătită pe dinăuntru.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pui-la-cuptor-cu-cartofi:s6', 'pui-la-cuptor-cu-cartofi', 5, 'Servește fierbinte, cu murături sau salată.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-mazare-cu-pui:s1', 'mancare-de-mazare-cu-pui', 0, 'Rumenește puiul în ulei 6–7 minute, cu sare și piper, apoi scoate-l din oală.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-mazare-cu-pui:s2', 'mancare-de-mazare-cu-pui', 1, 'În același ulei călește ceapa tocată și morcovii tăiați rondele, 5 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-mazare-cu-pui:s3', 'mancare-de-mazare-cu-pui', 2, 'Adaugă pasta de tomate și puiul la loc, apoi toarnă 300 ml de apă fierbinte. Acoperă și fierbe 15 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-mazare-cu-pui:s4', 'mancare-de-mazare-cu-pui', 3, 'Adaugă mazărea (nu e nevoie să o dezgheți) și fierbe încă 15–20 de minute la foc mic.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-mazare-cu-pui:s5', 'mancare-de-mazare-cu-pui', 4, 'Potrivește de sare și piper, apoi stinge focul și presară mărarul și pătrunjelul tocate.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocana-de-cartofi:s1', 'tocana-de-cartofi', 0, 'Curăță cartofii și taie-i cuburi de 2–3 cm.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocana-de-cartofi:s2', 'tocana-de-cartofi', 1, 'Călește ceapa tocată în ulei 5 minute, până devine sticloasă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocana-de-cartofi:s3', 'tocana-de-cartofi', 2, 'Adaugă pasta de tomate și boiaua și amestecă 1 minut, ca să nu se ardă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocana-de-cartofi:s4', 'tocana-de-cartofi', 3, 'Pune cartofii, dafinul, sare și piper. Toarnă apă cât să îi acopere pe jumătate.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocana-de-cartofi:s5', 'tocana-de-cartofi', 4, 'Fierbe la foc mic, cu capacul pus, 25 de minute, amestecând de două-trei ori, până se înmoaie cartofii și se îngroașă sosul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocana-de-cartofi:s6', 'tocana-de-cartofi', 5, 'Adaugă usturoiul pisat, pătrunjelul tocat și servește fierbinte.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('papricas-de-pui:s1', 'papricas-de-pui', 0, 'Călește ceapa tocată mărunt în ulei, la foc mic, 8 minute, până se înmoaie fără să se rumenească.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('papricas-de-pui:s2', 'papricas-de-pui', 1, 'Ia oala de pe foc, adaugă boiaua și pasta de tomate și amestecă, apoi pune-o la loc.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('papricas-de-pui:s3', 'papricas-de-pui', 2, 'Adaugă puiul, ardeiul tăiat cubulețe, sare și piper. Toarnă 200 ml de apă caldă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('papricas-de-pui:s4', 'papricas-de-pui', 3, 'Acoperă și fierbe la foc mic 35–40 de minute, până se înmoaie carnea.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('papricas-de-pui:s5', 'papricas-de-pui', 4, 'Amestecă smântâna cu făina și 3–4 linguri din sosul fierbinte, apoi toarn-o în oală.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('papricas-de-pui:s6', 'papricas-de-pui', 5, 'Mai fierbe 5 minute, amestecând. Presară pătrunjel, dacă vrei, și servește cu mămăligă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciulama-de-pui-cu-ciuperci:s1', 'ciulama-de-pui-cu-ciuperci', 0, 'Topește jumătate din unt într-o tigaie și rumenește puiul 6–7 minute, cu sare și piper. Scoate-l.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciulama-de-pui-cu-ciuperci:s2', 'ciulama-de-pui-cu-ciuperci', 1, 'În aceeași tigaie călește ceapa tocată 3 minute, apoi adaugă ciupercile și gătește 8 minute, până se evaporă lichidul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciulama-de-pui-cu-ciuperci:s3', 'ciulama-de-pui-cu-ciuperci', 2, 'Într-o oală mică, topește untul rămas, adaugă făina și amestecă 1 minut. Toarnă laptele încet, amestecând, până se îngroașă sosul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciulama-de-pui-cu-ciuperci:s4', 'ciulama-de-pui-cu-ciuperci', 3, 'Pune în sos puiul, ciupercile și usturoiul pisat. Fierbe la foc mic 15 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciulama-de-pui-cu-ciuperci:s5', 'ciulama-de-pui-cu-ciuperci', 4, 'Adaugă smântâna, nucșoara dacă vrei și sare după gust. Mai lasă 2–3 minute, fără să fiarbă tare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciulama-de-pui-cu-ciuperci:s6', 'ciulama-de-pui-cu-ciuperci', 5, 'Presară pătrunjel tocat și servește cu mămăligă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('iahnie-de-fasole:s1', 'iahnie-de-fasole', 0, 'Scurge fasolea înmuiată, acoperă-o cu apă rece și fierbe 10 minute. Aruncă apa și pune apă fierbinte proaspătă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('iahnie-de-fasole:s2', 'iahnie-de-fasole', 1, 'Fierbe fasolea la foc mic cu morcovul și dafinul, 60–70 de minute, până se înmoaie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('iahnie-de-fasole:s3', 'iahnie-de-fasole', 2, 'Călește ceapa tăiată mărunt în ulei, la foc mic, 15 minute, până se aurește.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('iahnie-de-fasole:s4', 'iahnie-de-fasole', 3, 'Adaugă pasta de tomate, boiaua și cimbrul și amestecă 1 minut.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('iahnie-de-fasole:s5', 'iahnie-de-fasole', 4, 'Toarnă ceapa peste fasole, adaugă sare și piper și fierbe împreună 15–20 de minute, până se îngroașă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('iahnie-de-fasole:s6', 'iahnie-de-fasole', 5, 'Adaugă usturoiul pisat și pătrunjelul tocat. Servește cu ceapă crudă și murături.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mici-la-gratar:s1', 'mici-la-gratar', 0, 'Pune carnea de mici într-un castron. Adaugă usturoiul pisat, bicarbonatul, cimbrul, boiaua, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mici-la-gratar:s2', 'mici-la-gratar', 1, 'Frământă 5–7 minute, adăugând 3–4 linguri de apă rece, până compoziția devine lipicioasă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mici-la-gratar:s3', 'mici-la-gratar', 2, 'Acoperă și lasă la rece cel puțin 1 oră, ca să se lege aromele.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mici-la-gratar:s4', 'mici-la-gratar', 3, 'Cu mâinile ude, formează rulouri cu lungimea de 8–9 cm.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mici-la-gratar:s5', 'mici-la-gratar', 4, 'Încinge grătarul sau o tigaie grill. Coace micii 10–12 minute, întorcându-i des, până se rumenesc uniform.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mici-la-gratar:s6', 'mici-la-gratar', 5, 'Servește imediat, cu muștar și pâine proaspătă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('drob-de-miel:s1', 'drob-de-miel', 0, 'Fierbe 2 ouă 10 minute, răcește-le și curăță-le de coajă. Fierbe organele în apă cu sare 20 de minute, apoi scurge-le și lasă-le să se răcească.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('drob-de-miel:s2', 'drob-de-miel', 1, 'Toacă organele fierte mărunt, la satâr sau la mașina de tocat. Încălzește cuptorul la 180 °C.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('drob-de-miel:s3', 'drob-de-miel', 2, 'Toacă ceapa verde, pătrunjelul și mărarul. Calește ceapa 3 minute în unt.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('drob-de-miel:s4', 'drob-de-miel', 3, 'Amestecă organele tocate cu verdeața, pâinea stoarsă, cele 5 ouă crude bătute, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('drob-de-miel:s5', 'drob-de-miel', 4, 'Unge o tavă dreptunghiulară cu unt și pune jumătate din compoziție. Așază cele 2 ouă fierte în lung, apoi acoperă cu restul de compoziție.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('drob-de-miel:s6', 'drob-de-miel', 5, 'Coace 50–60 de minute, până se rumenește deasupra și e ferm la atingere.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('drob-de-miel:s7', 'drob-de-miel', 6, 'Lasă drobul să se răcească complet în tavă, apoi taie-l felii.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('peste-la-cuptor-cu-legume:s1', 'peste-la-cuptor-cu-legume', 0, 'Încălzește cuptorul la 200°C.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('peste-la-cuptor-cu-legume:s2', 'peste-la-cuptor-cu-legume', 1, 'Taie cartofii rondele subțiri, ceapa felii, ardeiul fâșii și roșiile felii. Amestecă cartofii, ceapa și ardeiul cu jumătate din ulei, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('peste-la-cuptor-cu-legume:s3', 'peste-la-cuptor-cu-legume', 2, 'Întinde legumele în tavă și coace-le 20 de minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('peste-la-cuptor-cu-legume:s4', 'peste-la-cuptor-cu-legume', 3, 'Condimentează fileurile cu sare, piper, usturoi zdrobit și zeama de la jumătate de lămâie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('peste-la-cuptor-cu-legume:s5', 'peste-la-cuptor-cu-legume', 4, 'Așază peștele peste legume, adaugă roșiile și restul de ulei și coace încă 15–20 de minute, până se desface ușor cu furculița.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('peste-la-cuptor-cu-legume:s6', 'peste-la-cuptor-cu-legume', 5, 'Servește cu pătrunjel tocat și felii de lămâie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('saramura-de-crap:s1', 'saramura-de-crap', 0, 'Sărează feliile de crap și lasă-le 20 de minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('saramura-de-crap:s2', 'saramura-de-crap', 1, 'Încălzește uleiul în tigaie și rumenește peștele 6–8 minute pe fiecare parte. Scoate-l pe un platou.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('saramura-de-crap:s3', 'saramura-de-crap', 2, 'Într-o oală, fierbe 500 ml de apă cu 2 linguri de sare grunjoasă, dafinul, boabele de piper și ardeiul iute 5 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('saramura-de-crap:s4', 'saramura-de-crap', 3, 'Adaugă usturoiul pisat și boia și mai lasă 2 minute pe foc.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('saramura-de-crap:s5', 'saramura-de-crap', 4, 'Pune peștele în saramură și lasă-l la foc mic 10 minute, fără să fiarbă tare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('saramura-de-crap:s6', 'saramura-de-crap', 5, 'Servește cald, cu mămăligă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pastrav-la-gratar:s1', 'pastrav-la-gratar', 0, 'Spală păstrăvii și șterge-i bine. Freacă-i cu sare și piper, pe dinafară și pe dinăuntru.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pastrav-la-gratar:s2', 'pastrav-la-gratar', 1, 'Pune în burta fiecărui pește câteva fire de pătrunjel și o felie de lămâie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pastrav-la-gratar:s3', 'pastrav-la-gratar', 2, 'Unge peștii cu 2 linguri de ulei și lasă-i 10 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pastrav-la-gratar:s4', 'pastrav-la-gratar', 3, 'Încinge grătarul și coace peștii 8–10 minute pe fiecare parte, până se desprinde carnea de pe os.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pastrav-la-gratar:s5', 'pastrav-la-gratar', 4, 'Pentru mujdei, pisează usturoiul cu sare, adaugă restul de ulei, zeama de la o lămâie și 2 linguri de apă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pastrav-la-gratar:s6', 'pastrav-la-gratar', 5, 'Servește peștele fierbinte, cu mujdeiul deasupra.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('somon-la-cuptor-cu-lamaie:s1', 'somon-la-cuptor-cu-lamaie', 0, 'Încălzește cuptorul la 200°C.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('somon-la-cuptor-cu-lamaie:s2', 'somon-la-cuptor-cu-lamaie', 1, 'Taie cartofii noi în jumătăți, amestecă-i cu 2 linguri de ulei, sare și piper și coace-i 10 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('somon-la-cuptor-cu-lamaie:s3', 'somon-la-cuptor-cu-lamaie', 2, 'Împarte broccoli în buchete. Amestecă-le cu usturoiul tocat și restul de ulei.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('somon-la-cuptor-cu-lamaie:s4', 'somon-la-cuptor-cu-lamaie', 3, 'Adaugă broccoli în tavă, iar printre legume așază somonul, sărat și piperat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('somon-la-cuptor-cu-lamaie:s5', 'somon-la-cuptor-cu-lamaie', 4, 'Stoarce deasupra zeama de lămâie și pune câteva felii de lămâie pe pește.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('somon-la-cuptor-cu-lamaie:s6', 'somon-la-cuptor-cu-lamaie', 5, 'Coace 12–15 minute, până când somonul se desface ușor. Presară mărar tocat și servește.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('file-de-cod-cu-piure:s1', 'file-de-cod-cu-piure', 0, 'Curăță cartofii, taie-i bucăți și fierbe-i în apă cu sare 20 de minute, până se înmoaie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('file-de-cod-cu-piure:s2', 'file-de-cod-cu-piure', 1, 'Scurge cartofii și zdrobește-i. Adaugă untul și laptele încălzit și amestecă până obții un piure fin. Potrivește de sare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('file-de-cod-cu-piure:s3', 'file-de-cod-cu-piure', 2, 'Taie codul în porții, sărează-l, piperează-l și trece-l ușor prin făină.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('file-de-cod-cu-piure:s4', 'file-de-cod-cu-piure', 3, 'Încinge uleiul într-o tigaie și prăjește peștele 3–4 minute pe fiecare parte, până se rumenește.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('file-de-cod-cu-piure:s5', 'file-de-cod-cu-piure', 4, 'Servește codul peste piure, cu lămâie și mărar tocat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('macrou-la-cuptor:s1', 'macrou-la-cuptor', 0, 'Încălzește cuptorul la 200°C.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('macrou-la-cuptor:s2', 'macrou-la-cuptor', 1, 'Spală macroul și șterge-l. Fă 3 tăieturi pe fiecare parte și freacă-l cu sare, piper și cimbru.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('macrou-la-cuptor:s3', 'macrou-la-cuptor', 2, 'Pune în burta peștilor usturoi feliat și felii de lămâie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('macrou-la-cuptor:s4', 'macrou-la-cuptor', 3, 'Taie ceapa rondele și roșiile felii și întinde-le în tavă, pe un strat de ulei.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('macrou-la-cuptor:s5', 'macrou-la-cuptor', 4, 'Așază peștii deasupra, unge-i cu restul de ulei și coace 30–35 de minute, până se rumenesc.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('macrou-la-cuptor:s6', 'macrou-la-cuptor', 5, 'Servește cu pătrunjel tocat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-vinete:s1', 'salata-de-vinete', 0, 'Înțeapă vinetele cu o furculiță și coace-le în cuptor la 220°C, 35–40 de minute, întorcându-le o dată, până se înmoaie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-vinete:s2', 'salata-de-vinete', 1, 'Pune-le într-o strecurătoare, taie-le pe lung și lasă-le 15 minute să-și piardă zeama.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-vinete:s3', 'salata-de-vinete', 2, 'Curăță vinetele de coajă și toacă-le fin cu un cuțit de lemn sau de plastic.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-vinete:s4', 'salata-de-vinete', 3, 'Pune carnea într-un castron și adaugă puțină sare. Toarnă uleiul treptat, amestecând mereu, până devine cremoasă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-vinete:s5', 'salata-de-vinete', 4, 'Adaugă ceapa tocată mărunt, zeama de lămâie și potrivește de sare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-vinete:s6', 'salata-de-vinete', 5, 'Servește rece, cu felii de roșii și pâine proaspătă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-boeuf:s1', 'salata-de-boeuf', 0, 'Fierbe cartofii, morcovii și pătrunjelul cu coaja, 20–25 de minute, până se înmoaie. Lasă-i să se răcească.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-boeuf:s2', 'salata-de-boeuf', 1, 'Fierbe separat pieptul de pui în apă cu sare, 20 de minute. Lasă-l să se răcească în supă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-boeuf:s3', 'salata-de-boeuf', 2, 'Curăță legumele și taie-le cubulețe. Taie și puiul, și murăturile în cubulețe mici.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-boeuf:s4', 'salata-de-boeuf', 3, 'Scurge mazărea și pune totul într-un castron mare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-boeuf:s5', 'salata-de-boeuf', 4, 'Adaugă maioneza, muștarul, sare și piper și amestecă ușor.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-boeuf:s6', 'salata-de-boeuf', 5, 'Pune salata la rece cel puțin o oră. Servește cu ouă fierte tăiate felii.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-rosii-cu-castraveti:s1', 'salata-de-rosii-cu-castraveti', 0, 'Spală legumele. Taie roșiile felii sau cuburi mari și castraveții rondele.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-rosii-cu-castraveti:s2', 'salata-de-rosii-cu-castraveti', 1, 'Taie ceapa fâșii subțiri.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-rosii-cu-castraveti:s3', 'salata-de-rosii-cu-castraveti', 2, 'Pune totul într-un castron și adaugă sare, ulei și oțet.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-rosii-cu-castraveti:s4', 'salata-de-rosii-cu-castraveti', 3, 'Amestecă ușor, presară pătrunjel tocat și piper și servește imediat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-varza:s1', 'salata-de-varza', 0, 'Scoate frunzele de deasupra și cotorul verzei, apoi taie-o cât mai fin.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-varza:s2', 'salata-de-varza', 1, 'Presară 1 linguriță de sare și frământă varza cu mâinile 2 minute, până se înmoaie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-varza:s3', 'salata-de-varza', 2, 'Rade morcovul și adaugă-l peste varză.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-varza:s4', 'salata-de-varza', 3, 'Adaugă uleiul, oțetul, piperul și chimenul și amestecă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-varza:s5', 'salata-de-varza', 4, 'Lasă salata 10 minute înainte de servit, ca să se lege aromele.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-orientala:s1', 'salata-orientala', 0, 'Fierbe cartofii cu coaja în apă cu sare, 25–30 de minute, până se înmoaie. Fierbe ouăle tari, 10 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-orientala:s2', 'salata-orientala', 1, 'Curăță cartofii când s-au răcit puțin și taie-i rondele subțiri.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-orientala:s3', 'salata-orientala', 2, 'Taie ceapa foarte fin și presară-o peste cartofi, cu sare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-orientala:s4', 'salata-orientala', 3, 'Adaugă uleiul, oțetul și piperul și amestecă ușor, ca să nu se rupă cartofii.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-orientala:s5', 'salata-orientala', 4, 'Decorează cu ouăle tăiate felii, măsline și pătrunjel tocat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-fasole-verde:s1', 'salata-de-fasole-verde', 0, 'Curăță fasolea de capete și taie-o în bucăți de 4–5 cm.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-fasole-verde:s2', 'salata-de-fasole-verde', 1, 'Fierbe-o în apă clocotită cu sare 8–10 minute, până se înmoaie, dar rămâne puțin crocantă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-fasole-verde:s3', 'salata-de-fasole-verde', 2, 'Scurge-o și răcește-o sub apă rece, apoi lasă-o să se scurgă bine.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-fasole-verde:s4', 'salata-de-fasole-verde', 3, 'Pisează usturoiul cu puțină sare și amestecă-l cu uleiul și oțetul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-fasole-verde:s5', 'salata-de-fasole-verde', 4, 'Toarnă sosul peste fasole, adaugă piper și pătrunjel tocat și amestecă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-greceasca:s1', 'salata-greceasca', 0, 'Taie roșiile în felii groase, castraveții în rondele groase și ardeiul în inele.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-greceasca:s2', 'salata-greceasca', 1, 'Taie ceapa roșie în felii subțiri.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-greceasca:s3', 'salata-greceasca', 2, 'Pune legumele într-un bol și adaugă măslinele.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-greceasca:s4', 'salata-greceasca', 3, 'Amestecă uleiul de măsline cu oțetul, sare și piper și toarnă sosul peste legume.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-greceasca:s5', 'salata-greceasca', 4, 'Pune bucata de feta deasupra și presară oregano. Servește imediat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('dovlecei-pane:s1', 'dovlecei-pane', 0, 'Taie dovleceii rondele sau felii de 1 cm. Sărează-i și lasă-i 10 minute, apoi tamponează-i cu un prosop de hârtie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('dovlecei-pane:s2', 'dovlecei-pane', 1, 'Pregătește trei farfurii: făina, ouăle bătute cu piper și pesmetul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('dovlecei-pane:s3', 'dovlecei-pane', 2, 'Trece fiecare felie prin făină, apoi prin ou și la final prin pesmet.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('dovlecei-pane:s4', 'dovlecei-pane', 3, 'Încinge uleiul într-o tigaie și prăjește feliile 2–3 minute pe fiecare parte, până se rumenesc.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('dovlecei-pane:s5', 'dovlecei-pane', 4, 'Pune-le pe un prosop de hârtie, ca să scape de exces de ulei.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('dovlecei-pane:s6', 'dovlecei-pane', 5, 'Pentru sos, amestecă iaurtul cu usturoi pisat și puțină sare. Servește feliile calde.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-de-dovlecei:s1', 'chiftele-de-dovlecei', 0, 'Rade dovleceii, sărează-i și lasă-i 10 minute, apoi strânge bine zeama cu mâna.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-de-dovlecei:s2', 'chiftele-de-dovlecei', 1, 'Adaugă ouăle, telemeaua dată pe răzătoare, mărarul tocat și usturoiul pisat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-de-dovlecei:s3', 'chiftele-de-dovlecei', 2, 'Încorporează făina, piperul și puțină sare. Compoziția trebuie să se lege ușor.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-de-dovlecei:s4', 'chiftele-de-dovlecei', 3, 'Încinge uleiul în tigaie și pune compoziția cu lingura, formând chiftele mici.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-de-dovlecei:s5', 'chiftele-de-dovlecei', 4, 'Prăjește-le 3–4 minute pe fiecare parte, până se rumenesc, apoi scurge-le pe un prosop de hârtie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-spanac:s1', 'mancare-de-spanac', 0, 'Spală spanacul în mai multe ape, taie-i cozile și toacă frunzele.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-spanac:s2', 'mancare-de-spanac', 1, 'Fierbe spanacul 5 minute în puțină apă cu sare, apoi scurge-l și strânge-l ușor.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-spanac:s3', 'mancare-de-spanac', 2, 'Călește ceapa tocată în ulei la foc mic, 5 minute, până se înmoaie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-spanac:s4', 'mancare-de-spanac', 3, 'Adaugă făina și amestecă un minut, apoi pune spanacul și 200 ml de apă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-spanac:s5', 'mancare-de-spanac', 4, 'Fierbe la foc mic 10 minute, amestecând din când în când.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-spanac:s6', 'mancare-de-spanac', 5, 'Adaugă usturoiul pisat, sare și piper, mai lasă 2 minute pe foc și servește, cu smântână dacă vrei.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cartofi-taranesti:s1', 'cartofi-taranesti', 0, 'Încălzește cuptorul la 210°C.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cartofi-taranesti:s2', 'cartofi-taranesti', 1, 'Curăță cartofii și taie-i felii groase sau căței. Taie ceapa pene și usturoiul felii.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cartofi-taranesti:s3', 'cartofi-taranesti', 2, 'Amestecă cartofii cu ulei, boia, cimbru, sare și piper într-un castron.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cartofi-taranesti:s4', 'cartofi-taranesti', 3, 'Întinde cartofii într-o tavă mare, într-un singur strat, și adaugă ceapa.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cartofi-taranesti:s5', 'cartofi-taranesti', 4, 'Coace 30–35 de minute, amestecând o dată la jumătate, până se rumenesc.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cartofi-taranesti:s6', 'cartofi-taranesti', 5, 'Adaugă usturoiul în ultimele 5 minute. Servește cu pătrunjel tocat și ardei iute, dacă vrei.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('linte-cu-legume:s1', 'linte-cu-legume', 0, 'Spală lintea și scurge-o. Taie ceapa mărunt, iar morcovii și țelina cubulețe.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('linte-cu-legume:s2', 'linte-cu-legume', 1, 'Călește ceapa în ulei 3 minute, apoi adaugă morcovii și țelina și mai călește 5 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('linte-cu-legume:s3', 'linte-cu-legume', 2, 'Adaugă lintea, boia, dafinul și 1 litru de apă și fierbe la foc mic 25 de minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('linte-cu-legume:s4', 'linte-cu-legume', 3, 'Toarnă bulionul și fierbe încă 10 minute, până lintea e moale.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('linte-cu-legume:s5', 'linte-cu-legume', 4, 'Adaugă usturoiul pisat, sare și piper. Dacă vrei, pune oțetul la final.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('linte-cu-legume:s6', 'linte-cu-legume', 5, 'Scoate dafinul și servește fierbinte.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('fasole-batuta:s1', 'fasole-batuta', 0, 'Lasă fasolea la înmuiat în apă rece peste noapte, apoi scurge-o.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('fasole-batuta:s2', 'fasole-batuta', 1, 'Fierbe fasolea în apă proaspătă, la foc mic, 60–80 de minute, până se înmoaie complet. Sare abia la final.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('fasole-batuta:s3', 'fasole-batuta', 2, 'Scoate o parte din apa de fiert și zdrobește fasolea cu un tuci sau cu un blender de mână, adăugând apă până obții un piure gros.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('fasole-batuta:s4', 'fasole-batuta', 3, 'Adaugă usturoiul pisat, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('fasole-batuta:s5', 'fasole-batuta', 4, 'Taie ceapa felii subțiri și călește-o în ulei 8–10 minute, până se rumenește. La final, adaugă boia, dacă vrei.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('fasole-batuta:s6', 'fasole-batuta', 5, 'Pune fasolea în farfurii și toarnă ceapa călită deasupra.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciuperci-cu-smantana:s1', 'ciuperci-cu-smantana', 0, 'Fierbe 1 litru de apă cu sare, toarnă mălaiul în ploaie și amestecă 20–25 de minute, până se desprinde de pe oală.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciuperci-cu-smantana:s2', 'ciuperci-cu-smantana', 1, 'Șterge ciupercile cu un prosop umed și taie-le felii. Taie ceapa mărunt.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciuperci-cu-smantana:s3', 'ciuperci-cu-smantana', 2, 'Topește untul cu uleiul într-o tigaie și călește ceapa 3 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciuperci-cu-smantana:s4', 'ciuperci-cu-smantana', 3, 'Adaugă ciupercile și gătește-le 8–10 minute la foc mare, până dispare zeama.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciuperci-cu-smantana:s5', 'ciuperci-cu-smantana', 4, 'Adaugă usturoiul pisat, sare și piper, apoi smântâna. Fierbe 3 minute la foc mic.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciuperci-cu-smantana:s6', 'ciuperci-cu-smantana', 5, 'Presară mărar tocat și servește peste mămăligă fierbinte.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('vinete-la-cuptor-cu-rosii:s1', 'vinete-la-cuptor-cu-rosii', 0, 'Încălzește cuptorul la 200°C.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('vinete-la-cuptor-cu-rosii:s2', 'vinete-la-cuptor-cu-rosii', 1, 'Taie vinetele în jumătăți pe lung. Crestează carnea în romburi, sărează-o și unge-o cu jumătate din ulei.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('vinete-la-cuptor-cu-rosii:s3', 'vinete-la-cuptor-cu-rosii', 2, 'Coace vinetele 20 de minute, cu fața în sus.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('vinete-la-cuptor-cu-rosii:s4', 'vinete-la-cuptor-cu-rosii', 3, 'Taie roșiile cubulețe și amestecă-le cu usturoiul pisat, oregano, sare, piper și restul de ulei.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('vinete-la-cuptor-cu-rosii:s5', 'vinete-la-cuptor-cu-rosii', 4, 'Pune roșiile peste vinete, presară cașcavalul ras și coace încă 15–20 de minute, până se rumenește.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('vinete-la-cuptor-cu-rosii:s6', 'vinete-la-cuptor-cu-rosii', 5, 'Servește cald, cu busuioc proaspăt deasupra.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('spaghete-bolognese:s1', 'spaghete-bolognese', 0, 'Toacă mărunt ceapa, morcovul și usturoiul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('spaghete-bolognese:s2', 'spaghete-bolognese', 1, 'Încinge uleiul într-o tigaie adâncă și călește ceapa și morcovul 5 minute, apoi adaugă usturoiul încă un minut.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('spaghete-bolognese:s3', 'spaghete-bolognese', 2, 'Adaugă carnea tocată și sfărâm-o cu lingura. Prăjește-o 8–10 minute, până se rumenește.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('spaghete-bolognese:s4', 'spaghete-bolognese', 3, 'Pune pasta de tomate, roșiile din conservă strivite, oregano, sare și piper. Fierbe la foc mic 30 de minute, amestecând din când în când.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('spaghete-bolognese:s5', 'spaghete-bolognese', 4, 'Fierbe spaghetele în apă cu sare, după timpul de pe pachet, și scurge-le.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('spaghete-bolognese:s6', 'spaghete-bolognese', 5, 'Amestecă spaghetele cu sosul, servește cu parmezan ras și busuioc.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-carbonara:s1', 'paste-carbonara', 0, 'Pune la fiert pastele în apă cu sare, după timpul de pe pachet.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-carbonara:s2', 'paste-carbonara', 1, 'Taie baconul fâșii și prăjește-l fără ulei 5–6 minute, până devine crocant.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-carbonara:s3', 'paste-carbonara', 2, 'Bate ouăle într-un bol cu parmezanul ras și mult piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-carbonara:s4', 'paste-carbonara', 3, 'Scoate pastele cu o cană de apă de la fiert și scurge-le. Pune-le în tigaia cu bacon, pe foc stins.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-carbonara:s5', 'paste-carbonara', 4, 'Toarnă amestecul de ouă peste paste și întoarce repede, adăugând câte o lingură de apă de la fiert până obții un sos cremos.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-carbonara:s6', 'paste-carbonara', 5, 'Servește imediat, cu piper și parmezan deasupra.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('lasagna:s1', 'lasagna', 0, 'Călește ceapa și morcovul tocate în ulei 5 minute, apoi adaugă usturoiul și carnea tocată. Prăjește 10 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('lasagna:s2', 'lasagna', 1, 'Adaugă roșiile strivite și pasta de tomate, sare și piper. Fierbe la foc mic 25 de minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('lasagna:s3', 'lasagna', 2, 'Pentru sosul alb, topește untul, adaugă făina și amestecă un minut. Toarnă laptele treptat, amestecând, și fierbe 5 minute până se îngroașă. Potrivește de sare și nucșoară.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('lasagna:s4', 'lasagna', 3, 'Încălzește cuptorul la 190°C. Unge o tavă cu puțin sos alb și pune un strat de foi.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('lasagna:s5', 'lasagna', 4, 'Așază alternativ sos de carne, sos alb, mozzarella tăiată și foi, în 3–4 straturi. Termină cu sos alb, mozzarella și parmezan ras.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('lasagna:s6', 'lasagna', 5, 'Coace 35–40 de minute, până se rumenește deasupra. Lasă 10 minute să se odihnească înainte de tăiat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pizza-de-casa:s1', 'pizza-de-casa', 0, 'Amestecă făina cu drojdia, zahărul și sarea. Adaugă uleiul și aproximativ 300 ml de apă caldă și frământă 8–10 minute, până aluatul e elastic.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pizza-de-casa:s2', 'pizza-de-casa', 1, 'Acoperă aluatul și lasă-l la dospit 1 oră, până își dublează volumul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pizza-de-casa:s3', 'pizza-de-casa', 2, 'Pentru sos, strivește roșiile cu usturoiul, oregano, un praf de sare și puțin ulei.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pizza-de-casa:s4', 'pizza-de-casa', 3, 'Încălzește cuptorul la 250°C, cu tava înăuntru. Împarte aluatul în două și întinde fiecare bucată subțire.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pizza-de-casa:s5', 'pizza-de-casa', 4, 'Unge blatul cu sos, presară mozzarella tăiată și adaugă șunca sau ciupercile, dacă vrei.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pizza-de-casa:s6', 'pizza-de-casa', 5, 'Coace fiecare pizza 10–12 minute, până se rumenește marginea. Presară busuioc proaspăt.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chili-con-carne:s1', 'chili-con-carne', 0, 'Toacă ceapa, ardeiul și usturoiul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chili-con-carne:s2', 'chili-con-carne', 1, 'Încinge uleiul într-o oală și călește ceapa 4 minute, apoi adaugă ardeiul și usturoiul încă 2 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chili-con-carne:s3', 'chili-con-carne', 2, 'Adaugă carnea tocată și prăjește-o 10 minute, sfărâmând-o, până nu mai are zeamă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chili-con-carne:s4', 'chili-con-carne', 3, 'Pune boia afumată, chimenul, boia iute, pasta de tomate și roșiile strivite. Amestecă bine.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chili-con-carne:s5', 'chili-con-carne', 4, 'Adaugă fasolea scursă, sare și piper. Fierbe la foc mic 25–30 de minute, amestecând din când în când.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chili-con-carne:s6', 'chili-con-carne', 5, 'Servește fierbinte, cu o lingură de smântână deasupra.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('curry-de-pui:s1', 'curry-de-pui', 0, 'Taie pieptul de pui cubulețe și sărează-l ușor.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('curry-de-pui:s2', 'curry-de-pui', 1, 'Încinge uleiul și rumenește puiul 5 minute. Scoate-l din tigaie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('curry-de-pui:s3', 'curry-de-pui', 2, 'În același ulei, călește ceapa tocată 4 minute, apoi adaugă usturoiul, ghimbirul și curry. Amestecă un minut.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('curry-de-pui:s4', 'curry-de-pui', 3, 'Pune roșiile strivite și puiul înapoi în tigaie. Fierbe la foc mic 15 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('curry-de-pui:s5', 'curry-de-pui', 4, 'Adaugă smântâna și mai fierbe 5 minute. Potrivește de sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('curry-de-pui:s6', 'curry-de-pui', 5, 'Fierbe orezul în apă cu sare, 12–15 minute, și scurge-l. Servește curry-ul peste orez, cu pătrunjel tocat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('risotto-cu-ciuperci:s1', 'risotto-cu-ciuperci', 0, 'Dizolvă cuburile de supă în 1,2 l de apă și ține supa fierbinte, la foc mic.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('risotto-cu-ciuperci:s2', 'risotto-cu-ciuperci', 1, 'Taie ciupercile felii și călește-le în ulei, la foc mare, 6–7 minute, cu usturoiul zdrobit. Pune-le deoparte.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('risotto-cu-ciuperci:s3', 'risotto-cu-ciuperci', 2, 'Într-o oală, topește jumătate din unt și călește ceapa tocată mărunt 4 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('risotto-cu-ciuperci:s4', 'risotto-cu-ciuperci', 3, 'Adaugă orezul și amestecă 2 minute. Toarnă vinul, dacă folosești, și lasă să se evapore.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('risotto-cu-ciuperci:s5', 'risotto-cu-ciuperci', 4, 'Adaugă supa câte o polonic, amestecând mereu și așteptând să fie absorbită. După 18–20 de minute orezul e moale, dar are încă miez fin.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('risotto-cu-ciuperci:s6', 'risotto-cu-ciuperci', 5, 'Stinge focul, adaugă ciupercile, untul rămas și parmezanul. Amestecă, potrivește de sare și piper și servește cu pătrunjel.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-ton-si-rosii:s1', 'paste-cu-ton-si-rosii', 0, 'Pune pastele la fiert în apă cu sare, după timpul de pe pachet.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-ton-si-rosii:s2', 'paste-cu-ton-si-rosii', 1, 'Între timp, călește ceapa tocată și usturoiul în ulei 3–4 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-ton-si-rosii:s3', 'paste-cu-ton-si-rosii', 2, 'Adaugă roșiile strivite, oregano, sare și piper. Fierbe 8 minute la foc mediu.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-ton-si-rosii:s4', 'paste-cu-ton-si-rosii', 3, 'Scurge tonul și adaugă-l în sos, împreună cu măslinele și caperele, dacă folosești. Mai ține pe foc 2 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-ton-si-rosii:s5', 'paste-cu-ton-si-rosii', 4, 'Scurge pastele și amestecă-le cu sosul. Presară pătrunjel tocat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-caesar-cu-pui:s1', 'salata-caesar-cu-pui', 0, 'Taie pâinea cubulețe, unge-le cu o lingură de ulei și prăjește-le în tigaie sau la cuptor, la 200°C, 6–8 minute, până sunt crocante.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-caesar-cu-pui:s2', 'salata-caesar-cu-pui', 1, 'Condimentează pieptul de pui cu sare și piper și rumenește-l în restul de ulei, 5–6 minute pe fiecare parte. Lasă-l 5 minute să se odihnească, apoi taie-l felii.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-caesar-cu-pui:s3', 'salata-caesar-cu-pui', 2, 'Pentru dressing, amestecă maioneza cu zeama de lămâie, usturoiul zdrobit, muștarul și jumătate din parmezan.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-caesar-cu-pui:s4', 'salata-caesar-cu-pui', 3, 'Rupe salata în bucăți mari și amestec-o cu dressingul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-caesar-cu-pui:s5', 'salata-caesar-cu-pui', 4, 'Așază deasupra puiul, crutoanele și restul de parmezan. Servește imediat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('hummus:s1', 'hummus', 0, 'Lasă năutul la înmuiat în apă rece 8–12 ore. Scurge-l.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('hummus:s2', 'hummus', 1, 'Fierbe năutul în apă proaspătă, la foc mic, 50–60 de minute, până se zdrobește ușor între degete. Păstrează o cană din apa de fiert.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('hummus:s3', 'hummus', 2, 'Prăjește susanul în tigaie uscată 2 minute, apoi pisează-l sau mixează-l fin.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('hummus:s4', 'hummus', 3, 'Mixează năutul scurs cu susanul, zeama de lămâie, usturoiul, chimenul și sarea. Adaugă apă de la fiert, câte o lingură, până obții o cremă fină.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('hummus:s5', 'hummus', 4, 'Pune hummusul într-un bol, toarnă uleiul deasupra și presară boia dulce. Se păstrează 4 zile la frigider.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bowl-cu-pui-si-orez:s1', 'bowl-cu-pui-si-orez', 0, 'Încălzește cuptorul la 200°C. Amestecă sosul de soia cu mierea, usturoiul zdrobit și o lingură de ulei.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bowl-cu-pui-si-orez:s2', 'bowl-cu-pui-si-orez', 1, 'Taie pieptul de pui felii groase și învelește-l în sos. Lasă-l 10 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bowl-cu-pui-si-orez:s3', 'bowl-cu-pui-si-orez', 2, 'Taie broccoli în buchete, morcovii rondele și ardeiul fâșii. Amestecă-le cu uleiul rămas, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bowl-cu-pui-si-orez:s4', 'bowl-cu-pui-si-orez', 3, 'Pune puiul și legumele pe două tăvi și coace 20–25 de minute, întorcând o dată.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bowl-cu-pui-si-orez:s5', 'bowl-cu-pui-si-orez', 4, 'Fierbe orezul în apă cu sare, 12–15 minute, și scurge-l.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bowl-cu-pui-si-orez:s6', 'bowl-cu-pui-si-orez', 5, 'Împarte orezul, puiul și legumele în 4 caserole. Lasă-le să se răcească, apoi închide-le și pune-le la frigider, până la 4 zile. Presară susan înainte de mâncat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-la-cuptor-meal-prep:s1', 'chiftele-la-cuptor-meal-prep', 0, 'Încălzește cuptorul la 200°C.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-la-cuptor-meal-prep:s2', 'chiftele-la-cuptor-meal-prep', 1, 'Amestecă carnea cu oul, ceapa rasă, usturoiul, pesmetul, pătrunjelul tocat, boia, sare și piper. Formează chiftele cât o nucă mare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-la-cuptor-meal-prep:s3', 'chiftele-la-cuptor-meal-prep', 2, 'Taie cartofii și morcovii bucăți mici, iar dovleceii cuburi mai mari. Amestecă-i cu uleiul, cimbrul, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-la-cuptor-meal-prep:s4', 'chiftele-la-cuptor-meal-prep', 3, 'Întinde cartofii și morcovii pe o tavă mare și coace-i 15 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-la-cuptor-meal-prep:s5', 'chiftele-la-cuptor-meal-prep', 4, 'Adaugă dovleceii și chiftelele pe tavă și mai coace 25 de minute, întorcând chiftelele o dată, până sunt rumene.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-la-cuptor-meal-prep:s6', 'chiftele-la-cuptor-meal-prep', 5, 'Lasă să se răcească și împarte în 4 caserole. Se păstrează la frigider 3–4 zile.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('quesadilla-cu-pui:s1', 'quesadilla-cu-pui', 0, 'Taie pieptul de pui fâșii subțiri și condimentează-l cu boia afumată, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('quesadilla-cu-pui:s2', 'quesadilla-cu-pui', 1, 'Rumenește puiul în jumătate din ulei, 6–7 minute. Adaugă ardeiul și ceapa tăiate fâșii și porumbul scurs și mai gătește 4 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('quesadilla-cu-pui:s3', 'quesadilla-cu-pui', 2, 'Presară cașcaval pe jumătate din fiecare lipie, pune deasupra umplutura de pui și încă puțin cașcaval.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('quesadilla-cu-pui:s4', 'quesadilla-cu-pui', 3, 'Îndoaie lipiile în două.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('quesadilla-cu-pui:s5', 'quesadilla-cu-pui', 4, 'Rumenește fiecare quesadilla în tigaie încinsă cu puțin ulei, 2–3 minute pe fiecare parte, până se topește cașcavalul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('quesadilla-cu-pui:s6', 'quesadilla-cu-pui', 5, 'Taie în triunghiuri și servește cu smântână.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('papanasi:s1', 'papanasi', 0, 'Strânge brânza într-un tifon și lasă-o 10 minute să se scurgă. Apoi freac-o printr-o strecurătoare sau zdrobește-o bine cu furculița.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('papanasi:s2', 'papanasi', 1, 'Amestecă brânza cu ouăle, grisul, zahărul, zahărul vanilat, sarea și jumătate din făină.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('papanasi:s3', 'papanasi', 2, 'Adaugă făina rămasă amestecată cu praful de copt, cât să iasă un aluat moale, care se lipește puțin de mâini.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('papanasi:s4', 'papanasi', 3, 'Formează 12 bile și fă câte o gaură în mijloc, ca la gogoși. Pune deoparte bucățile scoase și lipește-le deasupra ca o căciuliță.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('papanasi:s5', 'papanasi', 4, 'Încinge uleiul la foc mediu și prăjește papanașii 3–4 minute pe fiecare parte, până se rumenesc. Scurge-i pe hârtie de bucătărie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('papanasi:s6', 'papanasi', 5, 'Servește călduți, cu smântână și dulceață deasupra.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('placinta-cu-mere:s1', 'placinta-cu-mere', 0, 'Amestecă făina cu praful de copt, untul rece tăiat cubulețe și 80 g de zahăr, frecând cu degetele până se face ca niște firimituri.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('placinta-cu-mere:s2', 'placinta-cu-mere', 1, 'Adaugă oul și smântâna și frământă repede un aluat neted. Împarte-l în două, înfășoară-l în folie și ține-l 30 de minute la frigider.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('placinta-cu-mere:s3', 'placinta-cu-mere', 2, 'Curăță merele și dă-le pe răzătoarea mare. Amestecă-le cu zahărul rămas, scorțișoara și zeama de lămâie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('placinta-cu-mere:s4', 'placinta-cu-mere', 3, 'Încălzește cuptorul la 180°C. Întinde jumătate din aluat și tapetează o tavă de 24 cm, unsă cu unt.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('placinta-cu-mere:s5', 'placinta-cu-mere', 4, 'Pune merele peste aluat. Întinde restul aluatului și acoperă plăcinta, apoi înțeapă-l în câteva locuri cu furculița.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('placinta-cu-mere:s6', 'placinta-cu-mere', 5, 'Coace 40–45 de minute, până se rumenește. Lasă să se răcească și presară zahăr pudră.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chec-cu-cacao:s1', 'chec-cu-cacao', 0, 'Încălzește cuptorul la 170°C și unge o formă de chec cu unt, apoi tapetează-o cu făină.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chec-cu-cacao:s2', 'chec-cu-cacao', 1, 'Mixează untul cu zahărul și zahărul vanilat până devine cremos. Adaugă ouăle pe rând, mixând după fiecare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chec-cu-cacao:s3', 'chec-cu-cacao', 2, 'Amestecă făina cu praful de copt și un praf de sare, apoi încorporează-le în compoziție, alternând cu laptele.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chec-cu-cacao:s4', 'chec-cu-cacao', 3, 'Împarte aluatul în două. Într-o jumătate amestecă cacaua.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chec-cu-cacao:s5', 'chec-cu-cacao', 4, 'Toarnă în formă, pe rând, cu lingura, aluatul alb și cel cu cacao. Trage o furculiță prin aluat ca să se marmoreze.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chec-cu-cacao:s6', 'chec-cu-cacao', 5, 'Coace 45–50 de minute. Verifică cu o scobitoare: trebuie să iasă uscată. Lasă checul 10 minute în formă, apoi scoate-l.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('orez-cu-lapte:s1', 'orez-cu-lapte', 0, 'Spală orezul sub jet de apă rece și scurge-l.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('orez-cu-lapte:s2', 'orez-cu-lapte', 1, 'Pune laptele la fiert într-o oală cu fundul gros, cu un praf de sare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('orez-cu-lapte:s3', 'orez-cu-lapte', 2, 'Când dă în clocot, adaugă orezul și coboară focul. Fierbe 25–30 de minute, amestecând des ca să nu se prindă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('orez-cu-lapte:s4', 'orez-cu-lapte', 3, 'Adaugă zahărul, zahărul vanilat și untul, dacă folosești. Mai fierbe 3–4 minute, până se îngroașă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('orez-cu-lapte:s5', 'orez-cu-lapte', 4, 'Împarte în boluri și presară scorțișoară deasupra.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-fructe:s1', 'salata-de-fructe', 0, 'Spală fructele. Curăță portocalele, kiwi și bananele și taie totul cubulețe, iar strugurii în jumătăți.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-fructe:s2', 'salata-de-fructe', 1, 'Stropește merele și bananele cu zeama de lămâie, ca să nu se închidă la culoare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-fructe:s3', 'salata-de-fructe', 2, 'Amestecă fructele într-un bol mare, cu miere dacă vrei desertul mai dulce.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-fructe:s4', 'salata-de-fructe', 3, 'Servește rece, cu iaurt și frunze de mentă. Mănâncă-o în aceeași zi.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('placinta-cu-branza:s1', 'placinta-cu-branza', 0, 'Încălzește cuptorul la 180°C și unge o tavă cu unt topit.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('placinta-cu-branza:s2', 'placinta-cu-branza', 1, 'Amestecă brânza cu ouăle, zahărul, zahărul vanilat, smântâna, un praf de sare, stafidele și coaja de lămâie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('placinta-cu-branza:s3', 'placinta-cu-branza', 2, 'Pune două foi în tavă, ungându-le cu unt topit între ele.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('placinta-cu-branza:s4', 'placinta-cu-branza', 3, 'Întinde jumătate din umplutură, acoperă cu încă două foi unse cu unt, apoi pune restul de umplutură.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('placinta-cu-branza:s5', 'placinta-cu-branza', 4, 'Acoperă cu foile rămase, unse bine cu unt, și taie plăcinta în pătrate, doar prin foile de sus.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('placinta-cu-branza:s6', 'placinta-cu-branza', 5, 'Coace 35–40 de minute, până se rumenește. Lasă-o 10 minute să se odihnească înainte de servit.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('briose-cu-afine:s1', 'briose-cu-afine', 0, 'Încălzește cuptorul la 180°C și pune în forma de brioșe 12 forme de hârtie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('briose-cu-afine:s2', 'briose-cu-afine', 1, 'Amestecă într-un bol făina, zahărul, zahărul vanilat, praful de copt și un praf de sare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('briose-cu-afine:s3', 'briose-cu-afine', 2, 'Bate ouăle cu laptele și uleiul, apoi toarnă lichidul peste ingredientele uscate. Amestecă doar cât să se încorporeze, fără să frămânți.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('briose-cu-afine:s4', 'briose-cu-afine', 3, 'Tăvălește afinele prin puțină făină, apoi adaugă-le în aluat, cu grijă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('briose-cu-afine:s5', 'briose-cu-afine', 4, 'Umple formele cu aluat, până la trei sferturi.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('briose-cu-afine:s6', 'briose-cu-afine', 5, 'Coace 20–22 de minute, până cresc și se rumenesc. Lasă-le 5 minute în tavă, apoi scoate-le pe un grătar.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cozonac-de-casa:s1', 'cozonac-de-casa', 0, 'Încălzește 200 ml de lapte până e caldut și dizolvă drojdia cu o lingură de zahăr și două linguri de făină. Lasă 10 minute, până face spumă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cozonac-de-casa:s2', 'cozonac-de-casa', 1, 'Amestecă făina rămasă cu restul de zahăr din aluat, zahărul vanilat, un praf de sare, două ouă și drojdia activată. Frământă 10 minute, apoi adaugă untul moale și frământă încă 10 minute, până aluatul e elastic.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cozonac-de-casa:s3', 'cozonac-de-casa', 2, 'Acoperă aluatul și lasă-l la dospit 1 oră și jumătate, într-un loc călduț, până își dublează volumul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cozonac-de-casa:s4', 'cozonac-de-casa', 3, 'Pentru umplutură, fierbe 100 ml de lapte cu zahărul, adaugă nucile, cacaua și esența de rom și amestecă. Lasă să se răcească.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cozonac-de-casa:s5', 'cozonac-de-casa', 4, 'Întinde aluatul dreptunghi, unge-l cu umplutura, rulează-l strâns, împătură-l în două și răsucește-l. Pune-l într-o tavă de 30 cm, tapetată cu hârtie de copt. Lasă-l încă 45 de minute la dospit.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cozonac-de-casa:s6', 'cozonac-de-casa', 5, 'Încălzește cuptorul la 180°C. Unge cozonacul cu oul bătut și coace 45–50 de minute. Dacă se rumenește prea repede, acoper-l cu folie de aluminiu.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cozonac-de-casa:s7', 'cozonac-de-casa', 6, 'Lasă-l să se răcească în tavă înainte de tăiat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('oua-umplute:s1', 'oua-umplute', 0, 'Fierbe ouăle 10 minute din momentul în care apa dă în clocot, apoi răcește-le în apă rece și curăță-le.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('oua-umplute:s2', 'oua-umplute', 1, 'Taie ouăle în jumătăți pe lungime și scoate gălbenușurile într-un bol.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('oua-umplute:s3', 'oua-umplute', 2, 'Zdrobește gălbenușurile cu furculița și amestecă-le cu maioneza, muștarul, ceapa verde tocată mărunt, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('oua-umplute:s4', 'oua-umplute', 3, 'Umple albușurile cu crema, cu o linguriță sau cu un pliculeț tăiat la colț, și presară puțină boia deasupra.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('oua-umplute:s5', 'oua-umplute', 4, 'Ține-le la rece până le servești.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('omleta-cu-sunca-si-cascaval:s1', 'omleta-cu-sunca-si-cascaval', 0, 'Bate ouăle cu laptele, puțină sare și piper, până se omogenizează.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('omleta-cu-sunca-si-cascaval:s2', 'omleta-cu-sunca-si-cascaval', 1, 'Taie șunca fâșii și toacă ceapa verde.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('omleta-cu-sunca-si-cascaval:s3', 'omleta-cu-sunca-si-cascaval', 2, 'Topește untul într-o tigaie antiaderentă la foc mediu și toarnă ouăle. Trage marginile spre centru cu o spatulă, cât încă e moale deasupra.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('omleta-cu-sunca-si-cascaval:s4', 'omleta-cu-sunca-si-cascaval', 3, 'Presară șunca, cașcavalul și ceapa verde pe o jumătate, împăturește omleta și mai las-o un minut, până se topește cașcavalul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('omleta-spaniola-cu-cartofi:s1', 'omleta-spaniola-cu-cartofi', 0, 'Curăță cartofii și taie-i felii subțiri; taie ceapa julienne.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('omleta-spaniola-cu-cartofi:s2', 'omleta-spaniola-cu-cartofi', 1, 'Încălzește uleiul într-o tigaie de 24 cm și gătește cartofii și ceapa la foc mic, acoperit, 15–20 de minute, până se înmoaie fără să se rumenească.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('omleta-spaniola-cu-cartofi:s3', 'omleta-spaniola-cu-cartofi', 2, 'Bate ouăle cu sare într-un bol mare. Scurge cartofii de ulei (păstrează 2 linguri în tigaie) și amestecă-i cu ouăle.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('omleta-spaniola-cu-cartofi:s4', 'omleta-spaniola-cu-cartofi', 3, 'Toarnă amestecul înapoi în tigaie și gătește la foc mic 6–8 minute, până se leagă marginile.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('omleta-spaniola-cu-cartofi:s5', 'omleta-spaniola-cu-cartofi', 4, 'Întoarce omleta cu ajutorul unei farfurii mari și mai las-o 3–4 minute pe cealaltă parte. Servește-o caldă sau rece, cu pătrunjel.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('shakshuka:s1', 'shakshuka', 0, 'Toacă ceapa, ardeiul și usturoiul. Călește-le în ulei, într-o tigaie largă, 6–7 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('shakshuka:s2', 'shakshuka', 1, 'Adaugă boiaua, roșiile din conservă, sare și piper. Fierbe sosul la foc mic 10 minute, până se îngroașă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('shakshuka:s3', 'shakshuka', 2, 'Fă 6 adâncituri în sos cu o lingură și sparge câte un ou în fiecare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('shakshuka:s4', 'shakshuka', 3, 'Acoperă tigaia și gătește 6–8 minute, până se întăresc albușurile, iar gălbenușurile rămân moi.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('shakshuka:s5', 'shakshuka', 4, 'Presară feta și pătrunjel tocat și servește cu pâine.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('clatite-americane-cu-banane:s1', 'clatite-americane-cu-banane', 0, 'Zdrobește o banană cu furculița. Amestecă-o cu ouăle, laptele și untul topit.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('clatite-americane-cu-banane:s2', 'clatite-americane-cu-banane', 1, 'Într-un alt bol, amestecă făina, zahărul, praful de copt și un praf de sare. Toarnă peste ele amestecul lichid și amestecă doar cât să nu mai vezi făină; câteva cocoloașe sunt în regulă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('clatite-americane-cu-banane:s3', 'clatite-americane-cu-banane', 2, 'Unge ușor o tigaie antiaderentă cu unt și pune câte 2–3 linguri de aluat. Gătește la foc mediu-mic până apar bule deasupra, apoi întoarce clătita încă un minut.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('clatite-americane-cu-banane:s4', 'clatite-americane-cu-banane', 3, 'Servește clătitele calde, cu felii din banana rămasă și miere.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('friganele:s1', 'friganele', 0, 'Bate ouăle cu laptele și un praf de sare într-o farfurie adâncă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('friganele:s2', 'friganele', 1, 'Încinge uleiul într-o tigaie la foc mediu.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('friganele:s3', 'friganele', 2, 'Înmoaie feliile de pâine pe ambele părți în ou, lasă să se scurgă puțin și pune-le în tigaie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('friganele:s4', 'friganele', 3, 'Prăjește-le 2–3 minute pe fiecare parte, până se rumenesc, și scoate-le pe hârtie de bucătărie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('friganele:s5', 'friganele', 4, 'Servește-le cu zahăr pudră sau cu telemea.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('toast-cu-avocado-si-ou:s1', 'toast-cu-avocado-si-ou', 0, 'Prăjește feliile de pâine.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('toast-cu-avocado-si-ou:s2', 'toast-cu-avocado-si-ou', 1, 'Zdrobește avocado cu zeama de lămâie, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('toast-cu-avocado-si-ou:s3', 'toast-cu-avocado-si-ou', 2, 'Prăjește ouăle ochiuri în uleiul de măsline, la foc mediu, 3 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('toast-cu-avocado-si-ou:s4', 'toast-cu-avocado-si-ou', 3, 'Întinde avocado pe pâine, pune oul deasupra și presară, dacă vrei, puțin ardei iute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pasta-de-branza-cu-marar:s1', 'pasta-de-branza-cu-marar', 0, 'Sfărâmă telemeaua cu furculița și amestec-o cu brânza de vaci și smântâna, până devine cremoasă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pasta-de-branza-cu-marar:s2', 'pasta-de-branza-cu-marar', 1, 'Toacă mărunt ceapa verde și mărarul și adaugă-le în brânză.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pasta-de-branza-cu-marar:s3', 'pasta-de-branza-cu-marar', 2, 'Gustă și pune sare doar dacă e nevoie: telemeaua e deja sărată. Presară puțină boia și servește cu pâine sau cu legume crude.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pate-de-ficat-de-pui:s1', 'pate-de-ficat-de-pui', 0, 'Curăță ficățeii de pieliță și de vinișoare și spală-i.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pate-de-ficat-de-pui:s2', 'pate-de-ficat-de-pui', 1, 'Călește ceapa tocată și morcovul ras în ulei, 8 minute, la foc mic.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pate-de-ficat-de-pui:s3', 'pate-de-ficat-de-pui', 2, 'Adaugă ficățeii și cimbrul și gătește-i 8–10 minute, întorcându-i, până nu mai sunt roz la mijloc. Pune sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pate-de-ficat-de-pui:s4', 'pate-de-ficat-de-pui', 3, 'Lasă amestecul să se răcească puțin, apoi pasează-l cu blenderul împreună cu untul, până devine o cremă fină.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pate-de-ficat-de-pui:s5', 'pate-de-ficat-de-pui', 4, 'Pune pateul în borcane sau în caserole și ține-l la frigider cel puțin 2 ore înainte să-l servești.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-icre:s1', 'salata-de-icre', 0, 'Pune icrele și miezul de pâine stors într-un bol și freacă-le cu un tel sau cu mixerul, la viteză mică, 2 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-icre:s2', 'salata-de-icre', 1, 'Toarnă uleiul în fir subțire, amestecând continuu, ca la maioneză. Din când în când adaugă câteva picături de zeamă de lămâie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-icre:s3', 'salata-de-icre', 2, 'Continuă până când salata devine deschisă la culoare și pufoasă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-icre:s4', 'salata-de-icre', 3, 'Toacă ceapa foarte mărunt și amestec-o la final, sau servește-o separat. Ține salata la rece și mănânc-o cu pâine prăjită.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciuperci-umplute-cu-branza:s1', 'ciuperci-umplute-cu-branza', 0, 'Încinge cuptorul la 200 °C. Șterge ciupercile cu un prosop umed, scoate-le cozile și toacă-le mărunt.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciuperci-umplute-cu-branza:s2', 'ciuperci-umplute-cu-branza', 1, 'Călește cozile tocate și usturoiul în unt 5 minute, apoi amestecă-le cu telemeaua sfărâmată, pătrunjelul tocat și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciuperci-umplute-cu-branza:s3', 'ciuperci-umplute-cu-branza', 2, 'Umple pălăriile ciupercilor cu amestecul și așază-le într-o tavă cu hârtie de copt.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciuperci-umplute-cu-branza:s4', 'ciuperci-umplute-cu-branza', 3, 'Presară cașcavalul și coace 15–20 de minute, până se rumenește deasupra.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paine-cu-usturoi-la-cuptor:s1', 'paine-cu-usturoi-la-cuptor', 0, 'Încinge cuptorul la 200 °C.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paine-cu-usturoi-la-cuptor:s2', 'paine-cu-usturoi-la-cuptor', 1, 'Amestecă untul cu usturoiul pisat, pătrunjelul tocat mărunt și un praf de sare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paine-cu-usturoi-la-cuptor:s3', 'paine-cu-usturoi-la-cuptor', 2, 'Taie bagheta în felii groase de 2 cm, fără să tai până jos, și unge cu unt între felii.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paine-cu-usturoi-la-cuptor:s4', 'paine-cu-usturoi-la-cuptor', 3, 'Înfășoară bagheta în folie de aluminiu și coace 8 minute, apoi desfă folia și mai lasă 3–4 minute, să se rumenească.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pizza-pe-lipie:s1', 'pizza-pe-lipie', 0, 'Încinge cuptorul la 220 °C și pune lipiile pe o tavă cu hârtie de copt.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pizza-pe-lipie:s2', 'pizza-pe-lipie', 1, 'Amestecă bulionul cu oregano și uleiul și întinde-l pe lipii.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pizza-pe-lipie:s3', 'pizza-pe-lipie', 2, 'Pune deasupra șunca tăiată fâșii, ciupercile feliate subțire, mozzarella ruptă bucăți și măslinele.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pizza-pe-lipie:s4', 'pizza-pe-lipie', 3, 'Coace 8–10 minute, până se topește brânza și se rumenesc marginile.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('briose-cu-sunca-si-cascaval:s1', 'briose-cu-sunca-si-cascaval', 0, 'Încinge cuptorul la 180 °C și pune hârtii în forma de brioșe.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('briose-cu-sunca-si-cascaval:s2', 'briose-cu-sunca-si-cascaval', 1, 'Amestecă făina cu praful de copt și sarea. Separat, bate ouăle cu laptele și uleiul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('briose-cu-sunca-si-cascaval:s3', 'briose-cu-sunca-si-cascaval', 2, 'Toarnă lichidele peste făină și amestecă scurt cu o lingură. Adaugă șunca tăiată cubulețe, cașcavalul și ceapa verde tocată.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('briose-cu-sunca-si-cascaval:s4', 'briose-cu-sunca-si-cascaval', 3, 'Împarte aluatul în cele 12 forme și coace 22–25 de minute, până când o scobitoare iese curată.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('briose-cu-sunca-si-cascaval:s5', 'briose-cu-sunca-si-cascaval', 4, 'Lasă-le 5 minute în formă, apoi scoate-le pe un grătar. Se păstrează 3 zile în frigider.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pateuri-cu-branza:s1', 'pateuri-cu-branza', 0, 'Încinge cuptorul la 200 °C. Amestecă telemeaua sfărâmată cu brânza de vaci, un ou și mărarul tocat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pateuri-cu-branza:s2', 'pateuri-cu-branza', 1, 'Întinde ușor foietajul și taie-l în pătrate de aproximativ 10 cm.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pateuri-cu-branza:s3', 'pateuri-cu-branza', 2, 'Pune câte o lingură de umplutură pe fiecare pătrat, îndoaie-l în triunghi și apasă marginile cu furculița.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pateuri-cu-branza:s4', 'pateuri-cu-branza', 3, 'Așază pateurile pe o tavă cu hârtie de copt, unge-le cu oul bătut și presară susan.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pateuri-cu-branza:s5', 'pateuri-cu-branza', 4, 'Coace 20–25 de minute, până se umflă și se rumenesc.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('crenvursti-in-foietaj:s1', 'crenvursti-in-foietaj', 0, 'Încinge cuptorul la 200 °C.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('crenvursti-in-foietaj:s2', 'crenvursti-in-foietaj', 1, 'Taie foietajul în 8 fâșii lungi, de aproximativ 3 cm lățime.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('crenvursti-in-foietaj:s3', 'crenvursti-in-foietaj', 2, 'Înfășoară fiecare crenvurst în spirală cu câte o fâșie și pune-i pe o tavă cu hârtie de copt.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('crenvursti-in-foietaj:s4', 'crenvursti-in-foietaj', 3, 'Unge-i cu ou bătut, presară susan și coace 18–20 de minute, până se rumenește aluatul. Servește-i cu muștar.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mamaliga-cu-lapte:s1', 'mamaliga-cu-lapte', 0, 'Pune la fiert 800 ml de apă cu sarea. Când fierbe, presară mălaiul în ploaie, amestecând continuu, ca să nu facă cocoloașe.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mamaliga-cu-lapte:s2', 'mamaliga-cu-lapte', 1, 'Fierbe mămăliga la foc mic 12–15 minute, amestecând des, până se desprinde de pe pereții oalei. Adaugă untul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mamaliga-cu-lapte:s3', 'mamaliga-cu-lapte', 2, 'Încălzește laptele, dacă îl vrei cald, și toarnă-l în boluri.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mamaliga-cu-lapte:s4', 'mamaliga-cu-lapte', 3, 'Pune mămăliga cu lingura în lapte, în bucăți, și servește imediat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cascaval-pane:s1', 'cascaval-pane', 0, 'Pune făina, ouăle bătute și pesmetul în trei farfurii.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cascaval-pane:s2', 'cascaval-pane', 1, 'Treci fiecare felie de cașcaval prin făină, ou, pesmet, apoi încă o dată prin ou și pesmet, ca să nu curgă la prăjit.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cascaval-pane:s3', 'cascaval-pane', 2, 'Încinge uleiul într-o tigaie la foc mediu și prăjește feliile 1–2 minute pe fiecare parte, până se rumenesc.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cascaval-pane:s4', 'cascaval-pane', 3, 'Scoate-le pe hârtie de bucătărie și servește-le imediat, cât sunt fierbinți.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('smoothie-cu-banane-si-fructe-de-padure:s1', 'smoothie-cu-banane-si-fructe-de-padure', 0, 'Curăță bananele și rupe-le în bucăți.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('smoothie-cu-banane-si-fructe-de-padure:s2', 'smoothie-cu-banane-si-fructe-de-padure', 1, 'Pune toate ingredientele în blender.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('smoothie-cu-banane-si-fructe-de-padure:s3', 'smoothie-cu-banane-si-fructe-de-padure', 2, 'Mixează 1–2 minute, până devine fin. Dacă e prea gros, mai adaugă puțin lapte. Servește imediat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ovaz-la-frigider-peste-noapte:s1', 'ovaz-la-frigider-peste-noapte', 0, 'Amestecă fulgii de ovăz cu laptele, iaurtul, mierea și scorțișoara.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ovaz-la-frigider-peste-noapte:s2', 'ovaz-la-frigider-peste-noapte', 1, 'Împarte amestecul în două borcane, închide-le și pune-le în frigider peste noapte, cel puțin 6 ore.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ovaz-la-frigider-peste-noapte:s3', 'ovaz-la-frigider-peste-noapte', 2, 'Dimineața adaugă mărul ras sau tăiat cubulețe și nucile tocate. Se păstrează 2 zile în frigider.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bruschete-cu-rosii:s1', 'bruschete-cu-rosii', 0, 'Taie roșiile cubulețe mici, scurge zeama și amestecă-le cu busuiocul rupt, 3 linguri de ulei, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bruschete-cu-rosii:s2', 'bruschete-cu-rosii', 1, 'Taie bagheta felii, unge-le cu uleiul rămas și prăjește-le în cuptor la 200 °C sau într-o tigaie, 2–3 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bruschete-cu-rosii:s3', 'bruschete-cu-rosii', 2, 'Freacă feliile calde cu cățelul de usturoi tăiat în jumătate.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('bruschete-cu-rosii:s4', 'bruschete-cu-rosii', 3, 'Pune roșiile pe pâine chiar înainte de servit, ca să rămână crocantă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tzatziki:s1', 'tzatziki', 0, 'Rade castravetele pe răzătoarea mare, sărează-l ușor și lasă-l 10 minute, apoi stoarce-l bine de zeamă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tzatziki:s2', 'tzatziki', 1, 'Amestecă iaurtul cu castravetele, usturoiul pisat, mărarul tocat, uleiul și oțetul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tzatziki:s3', 'tzatziki', 2, 'Gustă, potrivește de sare și ține sosul la rece cel puțin 30 de minute înainte de servit.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('guacamole:s1', 'guacamole', 0, 'Taie avocado în jumătăți, scoate sâmburele și pune miezul într-un bol.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('guacamole:s2', 'guacamole', 1, 'Zdrobește-l cu furculița împreună cu zeama de lime și sare, lăsând câteva bucăți.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('guacamole:s3', 'guacamole', 2, 'Toacă foarte mărunt ceapa, roșia fără semințe și ardeiul iute și amestecă-le în avocado.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('guacamole:s4', 'guacamole', 3, 'Servește imediat; dacă îl păstrezi, acoperă-l cu folie lipită de suprafață, ca să nu se înnegrească.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('briose-de-oua-cu-legume:s1', 'briose-de-oua-cu-legume', 0, 'Încinge cuptorul la 180 °C și unge o formă de 12 brioșe cu ulei.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('briose-de-oua-cu-legume:s2', 'briose-de-oua-cu-legume', 1, 'Toacă mărunt ardeiul, spanacul și ceapa verde și împarte-le în forme. Sfărâmă feta deasupra.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('briose-de-oua-cu-legume:s3', 'briose-de-oua-cu-legume', 2, 'Bate ouăle cu laptele, puțină sare și piper și toarnă-le peste legume, până la trei sferturi din fiecare formă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('briose-de-oua-cu-legume:s4', 'briose-de-oua-cu-legume', 3, 'Coace 18–20 de minute, până se umflă și nu mai sunt moi la mijloc.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('briose-de-oua-cu-legume:s5', 'briose-de-oua-cu-legume', 4, 'Lasă-le să se răcească 5 minute înainte să le scoți. Se păstrează 3–4 zile în frigider.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-ciuperci:s1', 'supa-crema-de-ciuperci', 0, 'Topește untul într-o oală și călește ceapa tocată 5 minute. Adaugă usturoiul și ciupercile feliate și gătește încă 8 minute, până lasă apă și scade.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-ciuperci:s2', 'supa-crema-de-ciuperci', 1, 'Adaugă cartoful tăiat cubulețe, cimbrul și 1 l de apă caldă. Fierbe 15 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-ciuperci:s3', 'supa-crema-de-ciuperci', 2, 'Păstrează câteva felii de ciuperci pentru ornat și pasează restul cu blenderul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-ciuperci:s4', 'supa-crema-de-ciuperci', 3, 'Adaugă smântâna, sare și piper și încălzește supa fără să fiarbă. Servește cu pătrunjel și feliile păstrate.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-broccoli:s1', 'supa-crema-de-broccoli', 0, 'Desparte broccoli în buchețele și curăță tulpina, apoi taie-o cubulețe.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-broccoli:s2', 'supa-crema-de-broccoli', 1, 'Călește ceapa și usturoiul în ulei 4 minute. Adaugă cartofii tăiați cubulețe, tulpina de broccoli și 1 l de apă. Fierbe 10 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-broccoli:s3', 'supa-crema-de-broccoli', 2, 'Pune buchețelele de broccoli și mai fierbe 7–8 minute, doar cât se înmoaie, ca să rămână verzi.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-broccoli:s4', 'supa-crema-de-broccoli', 3, 'Pasează supa cu blenderul, adaugă cașcavalul, sare și piper și amestecă până se topește.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-cartofi:s1', 'supa-de-cartofi', 0, 'Curăță cartofii și morcovul și taie-le cubulețe.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-cartofi:s2', 'supa-de-cartofi', 1, 'Pune-le la fiert în 2 l de apă cu sare și foile de dafin, 15–20 de minute, până se înmoaie cartofii.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-cartofi:s3', 'supa-de-cartofi', 2, 'Călește ceapa tocată în ulei 5 minute, presară făina și boiaua, amestecă un minut și stinge cu un polonic de supă. Toarnă rântașul în oală.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-cartofi:s4', 'supa-de-cartofi', 3, 'Amestecă smântâna cu oțetul și cu un polonic de supă, apoi toarnă-o în oală, amestecând.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-cartofi:s5', 'supa-de-cartofi', 4, 'Încălzește supa fără să fiarbă tare, ca să nu se taie smântâna, adaugă tarhonul tocat și potrivește de sare și de acru.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-fasole-verde:s1', 'ciorba-de-fasole-verde', 0, 'Taie fasolea în bucăți de 2–3 cm, iar ceapa, morcovul, ardeiul și cartofii cubulețe.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-fasole-verde:s2', 'ciorba-de-fasole-verde', 1, 'Călește ceapa, morcovul și ardeiul în ulei 5 minute. Adaugă 2,5 l de apă caldă și fasolea și fierbe 15 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-fasole-verde:s3', 'ciorba-de-fasole-verde', 2, 'Pune cartofii și fierbe încă 10 minute, apoi roșiile tăiate cubulețe încă 5 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-fasole-verde:s4', 'ciorba-de-fasole-verde', 3, 'Toarnă borșul fiert separat, potrivește de sare și lasă să dea un clocot. Stinge focul și presară mărarul și pătrunjelul tocate.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-linte:s1', 'supa-de-linte', 0, 'Spală lintea în mai multe ape și las-o la scurs.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-linte:s2', 'supa-de-linte', 1, 'Călește ceapa, morcovii și țelina tăiate mărunt în ulei 6 minute. Adaugă usturoiul și cimbrul încă un minut.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-linte:s3', 'supa-de-linte', 2, 'Pune lintea, roșiile și 1,8 l de apă. Fierbe la foc mic, acoperit, 30 de minute, până se înmoaie lintea.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-linte:s4', 'supa-de-linte', 3, 'Pasează jumătate din supă, ca să se îngroașe, sau las-o așa. Potrivește cu sare, piper și zeamă de lămâie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-urzici:s1', 'ciorba-de-urzici', 0, 'Cu mănuși, alege frunzele și vârfurile de urzici și spală-le bine. Opărește-le 2 minute în apă clocotită, scurge-le și toacă-le.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-urzici:s2', 'ciorba-de-urzici', 1, 'Călește ceapa verde tocată și morcovul ras în ulei 4 minute. Adaugă 2 l de apă și orezul spălat și fierbe 15 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-urzici:s3', 'ciorba-de-urzici', 2, 'Adaugă urzicile și fierbe încă 5 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-urzici:s4', 'ciorba-de-urzici', 3, 'Toarnă borșul fiert separat, sare după gust și lasă să dea un clocot. Presară mărarul și servește cu smântână.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-legume-cu-fidea:s1', 'supa-de-legume-cu-fidea', 0, 'Curăță zarzavatul și cartofii și taie-le cubulețe mici.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-legume-cu-fidea:s2', 'supa-de-legume-cu-fidea', 1, 'Călește ceapa în ulei 3 minute, apoi adaugă morcovii, pătrunjelul și țelina și mai gătește 3 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-legume-cu-fidea:s3', 'supa-de-legume-cu-fidea', 2, 'Toarnă 2,5 l de apă, pune sare și fierbe 15 minute. Adaugă cartofii și fierbe încă 10 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-de-legume-cu-fidea:s4', 'supa-de-legume-cu-fidea', 3, 'Pune fideaua și fierbe 3–4 minute, după timpul de pe pachet. Presară pătrunjel verde tocat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-cartofi:s1', 'ciorba-de-cartofi', 0, 'Taie ceapa, morcovul și ardeiul cubulețe și călește-le în ulei 5 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-cartofi:s2', 'ciorba-de-cartofi', 1, 'Adaugă 2 l de apă și cartofii tăiați cuburi. Fierbe 20 de minute, până se înmoaie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-cartofi:s3', 'ciorba-de-cartofi', 2, 'Pune bulionul și borșul fiert separat și lasă să dea în clocot.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-cartofi:s4', 'ciorba-de-cartofi', 3, 'Potrivește de sare, stinge focul și adaugă leușteanul tocat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-praz:s1', 'supa-crema-de-praz', 0, 'Taie prazul rondele și spală-l bine de pământ. Curăță cartofii și taie-i cuburi.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-praz:s2', 'supa-crema-de-praz', 1, 'Călește prazul în unt, la foc mic, 8 minute, până se înmoaie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-praz:s3', 'supa-crema-de-praz', 2, 'Adaugă cartofii și 1 l de apă cu sare. Fierbe 15 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-praz:s4', 'supa-crema-de-praz', 3, 'Pasează supa, adaugă smântâna, puțină nucșoară și piper și încălzește fără să fiarbă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-mazare:s1', 'supa-crema-de-mazare', 0, 'Călește ceapa tocată în unt 4 minute. Adaugă cartoful tăiat cubulețe mici și 900 ml de apă și fierbe 8 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-mazare:s2', 'supa-crema-de-mazare', 1, 'Pune mazărea și fierbe 4–5 minute, doar cât se încălzește bine.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-mazare:s3', 'supa-crema-de-mazare', 2, 'Adaugă frunzele de mentă și pasează supa. Potrivește cu sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-crema-de-mazare:s4', 'supa-crema-de-mazare', 3, 'Servește cu câte o lingură de iaurt deasupra.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-fasole-verde:s1', 'mancare-de-fasole-verde', 0, 'Taie fasolea în bucăți de 3 cm și fierbe-o 10 minute în apă cu sare, apoi scurge-o.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-fasole-verde:s2', 'mancare-de-fasole-verde', 1, 'Călește ceapa tocată în ulei 5 minute. Adaugă roșiile tăiate cubulețe și bulionul și fierbe 5 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-fasole-verde:s3', 'mancare-de-fasole-verde', 2, 'Pune fasolea, usturoiul pisat și un pahar de apă. Înăbușă la foc mic, acoperit, 15 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-fasole-verde:s4', 'mancare-de-fasole-verde', 3, 'Potrivește cu sare și piper și presară mărarul tocat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('varza-calita-de-post:s1', 'varza-calita-de-post', 0, 'Taie varza fideluță și freac-o puțin cu sare, cu mâinile, ca să lase apă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('varza-calita-de-post:s2', 'varza-calita-de-post', 1, 'Călește ceapa tocată în ulei 5 minute, într-o oală mare, apoi adaugă varza și boiaua și amestecă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('varza-calita-de-post:s3', 'varza-calita-de-post', 2, 'Pune dafinul, cimbrul și o cană de apă. Înăbușă la foc mic, acoperit, 30 de minute, amestecând din când în când.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('varza-calita-de-post:s4', 'varza-calita-de-post', 3, 'Adaugă bulionul și piperul și mai lasă 10 minute, descoperit, până scade sosul. Presară mărar.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-praz-cu-orez:s1', 'mancare-de-praz-cu-orez', 0, 'Taie prazul rondele de 1 cm și spală-l bine.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-praz-cu-orez:s2', 'mancare-de-praz-cu-orez', 1, 'Călește prazul în ulei 8 minute, la foc mediu, până se înmoaie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-praz-cu-orez:s3', 'mancare-de-praz-cu-orez', 2, 'Adaugă orezul spălat, bulionul, dafinul, sare, piper și 600 ml de apă caldă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-praz-cu-orez:s4', 'mancare-de-praz-cu-orez', 3, 'Fierbe la foc mic, acoperit, 18–20 de minute, până se umflă orezul. Presară pătrunjel tocat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-mazare-de-post:s1', 'mancare-de-mazare-de-post', 0, 'Călește ceapa tocată și morcovul ras în ulei 5 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-mazare-de-post:s2', 'mancare-de-mazare-de-post', 1, 'Presară făina, amestecă un minut, apoi adaugă mazărea și 300 ml de apă caldă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-mazare-de-post:s3', 'mancare-de-mazare-de-post', 2, 'Fierbe la foc mic 10 minute, apoi pune bulionul, sare și piper și mai fierbe 10 minute, până se leagă sosul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-mazare-de-post:s4', 'mancare-de-mazare-de-post', 3, 'Stinge focul și presară mărarul tocat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('conopida-gratinata:s1', 'conopida-gratinata', 0, 'Desparte conopida în buchețele și fierbe-o 6–7 minute în apă cu sare. Scurge-o bine și pune-o într-un vas de cuptor.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('conopida-gratinata:s2', 'conopida-gratinata', 1, 'Topește untul într-o crăticioară, adaugă făina și amestecă un minut. Toarnă laptele treptat, amestecând cu telul, până se îngroașă sosul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('conopida-gratinata:s3', 'conopida-gratinata', 2, 'Pune în sos jumătate din cașcaval, sare, piper și puțină nucșoară și toarnă-l peste conopidă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('conopida-gratinata:s4', 'conopida-gratinata', 3, 'Presară restul de cașcaval și coace la 200 °C 20 de minute, până se rumenește.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cartofi-noi-cu-marar:s1', 'cartofi-noi-cu-marar', 0, 'Spală bine cartofii, frecându-i cu un burete, și fierbe-i în coajă, în apă cu sare, 15–20 de minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cartofi-noi-cu-marar:s2', 'cartofi-noi-cu-marar', 1, 'Scurge-i și taie-i în jumătăți pe cei mai mari.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cartofi-noi-cu-marar:s3', 'cartofi-noi-cu-marar', 2, 'Topește untul într-o tigaie largă, adaugă usturoiul pisat și cartofii și amestecă 2 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cartofi-noi-cu-marar:s4', 'cartofi-noi-cu-marar', 3, 'Presară mărarul tocat și servește-i cu iaurt rece.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('piure-de-cartofi:s1', 'piure-de-cartofi', 0, 'Curăță cartofii, taie-i în bucăți egale și pune-i la fiert în apă rece cu sare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('piure-de-cartofi:s2', 'piure-de-cartofi', 1, 'Fierbe-i 15–20 de minute, până intră ușor furculița, apoi scurge-i bine.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('piure-de-cartofi:s3', 'piure-de-cartofi', 2, 'Încălzește laptele cu untul. Zdrobește cartofii cu un zdrobitor, nu cu blenderul, ca să nu devină lipicioși.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('piure-de-cartofi:s4', 'piure-de-cartofi', 3, 'Adaugă laptele cald treptat, amestecând, până ajungi la consistența dorită. Potrivește de sare și pune puțină nucșoară.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cartofi-gratinati:s1', 'cartofi-gratinati', 0, 'Încinge cuptorul la 180 °C și unge un vas termorezistent cu unt.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cartofi-gratinati:s2', 'cartofi-gratinati', 1, 'Curăță cartofii și taie-i felii subțiri, de 3 mm.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cartofi-gratinati:s3', 'cartofi-gratinati', 2, 'Încălzește smântâna cu laptele, usturoiul pisat, sare, piper și nucșoară, fără să fiarbă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cartofi-gratinati:s4', 'cartofi-gratinati', 3, 'Așază cartofii în straturi în vas, turnând din sos peste fiecare strat. La final presară cașcavalul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cartofi-gratinati:s5', 'cartofi-gratinati', 4, 'Acoperă cu folie și coace 40 de minute, apoi scoate folia și mai coace 20 de minute, până se rumenește și cartofii sunt moi.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('orez-cu-legume:s1', 'orez-cu-legume', 0, 'Spală orezul până când apa iese limpede.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('orez-cu-legume:s2', 'orez-cu-legume', 1, 'Călește ceapa, morcovul și ardeiul tăiate cubulețe în ulei 5 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('orez-cu-legume:s3', 'orez-cu-legume', 2, 'Adaugă orezul și amestecă 2 minute, până devine sticlos. Toarnă 600 ml de apă fierbinte, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('orez-cu-legume:s4', 'orez-cu-legume', 3, 'Fierbe acoperit, la foc mic, 12 minute. Pune mazărea și porumbul scurs, acoperă și mai lasă 5 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('orez-cu-legume:s5', 'orez-cu-legume', 4, 'Stinge focul, lasă oala acoperită 5 minute, apoi afânează orezul cu furculița și presară pătrunjel.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocanita-de-ciuperci:s1', 'tocanita-de-ciuperci', 0, 'Taie ciupercile în sferturi și ceapa mărunt.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocanita-de-ciuperci:s2', 'tocanita-de-ciuperci', 1, 'Călește ceapa în ulei 5 minute. Adaugă ciupercile și gătește la foc mare 8 minute, până scade apa pe care o lasă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocanita-de-ciuperci:s3', 'tocanita-de-ciuperci', 2, 'Pune bulionul, cimbrul, dafinul, usturoiul pisat, sare, piper și 150 ml de apă. Înăbușă la foc mic 10 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocanita-de-ciuperci:s4', 'tocanita-de-ciuperci', 3, 'Presară pătrunjel tocat și servește cald.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ardei-umpluti-de-post:s1', 'ardei-umpluti-de-post', 0, 'Taie capacele ardeilor și scoate semințele.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ardei-umpluti-de-post:s2', 'ardei-umpluti-de-post', 1, 'Călește ceapa tocată, morcovii rași și ciupercile tocate în ulei 8 minute. Adaugă orezul spălat și amestecă 2 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ardei-umpluti-de-post:s3', 'ardei-umpluti-de-post', 2, 'Ia de pe foc, pune verdeața tocată, cimbrul, sare și piper și umple ardeii, fără să-i îndesi.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ardei-umpluti-de-post:s4', 'ardei-umpluti-de-post', 3, 'Așază ardeii în picioare într-o oală, toarnă bulionul amestecat cu apă cât să-i acopere pe trei sferturi și pune sare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ardei-umpluti-de-post:s5', 'ardei-umpluti-de-post', 4, 'Fierbe la foc mic, acoperit, 45–50 de minute, până se înmoaie orezul. Poți să-i dai la final 15 minute la cuptor, să se rumenească.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-de-cartofi:s1', 'chiftele-de-cartofi', 0, 'Fierbe cartofii curățați în apă cu sare, scurge-i bine și pasează-i. Lasă piureul să se răcească.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-de-cartofi:s2', 'chiftele-de-cartofi', 1, 'Toacă ceapa foarte mărunt și amestec-o în piure cu ouăle, făina, mărarul, telemeaua sfărâmată, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-de-cartofi:s3', 'chiftele-de-cartofi', 2, 'Cu mâinile ude, formează chiftele turtite și dă-le prin pesmet.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-de-cartofi:s4', 'chiftele-de-cartofi', 3, 'Prăjește-le în ulei încins, la foc mediu, 3 minute pe fiecare parte, până se rumenesc. Scoate-le pe hârtie de bucătărie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-ardei-copti:s1', 'salata-de-ardei-copti', 0, 'Coace ardeii pe plită, pe grătar sau în cuptor la 220 °C, 20–25 de minute, întorcându-i, până se înnegrește coaja.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-ardei-copti:s2', 'salata-de-ardei-copti', 1, 'Pune-i într-un vas acoperit sau într-o pungă 10 minute, ca să se desprindă ușor coaja, apoi curăță-i și scoate semințele.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-ardei-copti:s3', 'salata-de-ardei-copti', 2, 'Amestecă oțetul cu uleiul, zahărul, sare și usturoiul pisat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-ardei-copti:s4', 'salata-de-ardei-copti', 3, 'Rupe ardeii fâșii, toarnă sosul peste ei și presară pătrunjel. Ține-i la rece; sunt mai buni a doua zi.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-sfecla-rosie:s1', 'salata-de-sfecla-rosie', 0, 'Spală sfecla, înfășoar-o în folie de aluminiu și coace-o la 200 °C 50–60 de minute (sau fierbe-o în apă), până intră ușor cuțitul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-sfecla-rosie:s2', 'salata-de-sfecla-rosie', 1, 'Las-o să se răcească, curăț-o și rade-o pe răzătoarea mare sau taie-o felii subțiri.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-sfecla-rosie:s3', 'salata-de-sfecla-rosie', 2, 'Amestecă oțetul cu uleiul, zahărul, sarea, hreanul și chimenul și toarnă peste sfeclă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-sfecla-rosie:s4', 'salata-de-sfecla-rosie', 3, 'Pune salata într-un borcan și las-o la rece câteva ore, să se pătrundă. Se păstrează 4–5 zile.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-telina:s1', 'salata-de-telina', 0, 'Curăță țelina și rade-o pe răzătoarea mare. Stropește-o imediat cu zeamă de lămâie, ca să nu se înnegrească.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-telina:s2', 'salata-de-telina', 1, 'Amestecă maioneza cu iaurtul și puțină sare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-telina:s3', 'salata-de-telina', 2, 'Pune sosul peste țelină, amestecă bine și presară nucile tocate. Ține salata la rece 30 de minute înainte de servit.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('snitel-de-pui:s1', 'snitel-de-pui', 0, 'Taie pieptul de pui în felii de 1 cm, acoperă-le cu folie și bate-le cu ciocanul de carne până ajung la jumătate de centimetru. Sărează-le și piperează-le.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('snitel-de-pui:s2', 'snitel-de-pui', 1, 'Pune făina, ouăle bătute cu un praf de sare și pesmetul în trei farfurii.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('snitel-de-pui:s3', 'snitel-de-pui', 2, 'Treci fiecare felie prin făină, ou și pesmet, apăsând ușor ca să se lipească.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('snitel-de-pui:s4', 'snitel-de-pui', 3, 'Prăjește șnițelele în uleiul încins, la foc mediu, 3–4 minute pe fiecare parte, până sunt aurii și pătrunse.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('snitel-de-pui:s5', 'snitel-de-pui', 4, 'Scoate-le pe hârtie de bucătărie și servește-le cu felii de lămâie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('piept-de-pui-cu-usturoi-la-tigaie:s1', 'piept-de-pui-cu-usturoi-la-tigaie', 0, 'Taie fiecare piept în două pe grosime, ca să ai felii egale, și condimentează-le cu sare, piper și cimbru.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('piept-de-pui-cu-usturoi-la-tigaie:s2', 'piept-de-pui-cu-usturoi-la-tigaie', 1, 'Încinge uleiul într-o tigaie la foc mediu-mare și rumenește feliile 4–5 minute pe o parte, fără să le miști.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('piept-de-pui-cu-usturoi-la-tigaie:s3', 'piept-de-pui-cu-usturoi-la-tigaie', 2, 'Întoarce-le, adaugă untul și usturoiul strivit și gătește încă 4–5 minute, stropind carnea cu untul topit.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('piept-de-pui-cu-usturoi-la-tigaie:s4', 'piept-de-pui-cu-usturoi-la-tigaie', 3, 'Stropește cu zeamă de lămâie, lasă carnea 3 minute să se odihnească și apoi taie-o.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('frigarui-de-pui-la-cuptor:s1', 'frigarui-de-pui-la-cuptor', 0, 'Taie puiul cuburi de 3 cm și amestecă-l cu iaurtul, usturoiul pisat, boiaua, uleiul, sare și piper. Lasă-l la frigider cel puțin 30 de minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('frigarui-de-pui-la-cuptor:s2', 'frigarui-de-pui-la-cuptor', 1, 'Încinge cuptorul la 220 °C. Taie ardeii și ceapa în bucăți cât cuburile de carne.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('frigarui-de-pui-la-cuptor:s3', 'frigarui-de-pui-la-cuptor', 2, 'Înșiră pe bețe, pe rând, carnea, ardeiul și ceapa. Dacă bețele sunt de lemn, ține-le înainte 20 de minute în apă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('frigarui-de-pui-la-cuptor:s4', 'frigarui-de-pui-la-cuptor', 3, 'Așază frigăruile pe o tavă cu hârtie de copt și coace-le 18–20 de minute, întorcându-le o dată, până se rumenesc.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('aripioare-de-pui-la-cuptor:s1', 'aripioare-de-pui-la-cuptor', 0, 'Încinge cuptorul la 200 °C. Taie aripioarele la încheieturi și aruncă vârfurile sau păstrează-le pentru supă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('aripioare-de-pui-la-cuptor:s2', 'aripioare-de-pui-la-cuptor', 1, 'Amestecă uleiul cu boiaua și piperul și unge aripioarele. Așază-le pe o tavă cu hârtie de copt, într-un singur strat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('aripioare-de-pui-la-cuptor:s3', 'aripioare-de-pui-la-cuptor', 2, 'Coace-le 30 de minute, până încep să se rumenească.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('aripioare-de-pui-la-cuptor:s4', 'aripioare-de-pui-la-cuptor', 3, 'Amestecă mierea cu sosul de soia și usturoiul pisat, unge aripioarele și mai coace 12–15 minute, până se caramelizează.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pulpe-de-pui-cu-sos-de-usturoi:s1', 'pulpe-de-pui-cu-sos-de-usturoi', 0, 'Condimentează pulpele cu sare, piper, boia și cimbru.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pulpe-de-pui-cu-sos-de-usturoi:s2', 'pulpe-de-pui-cu-sos-de-usturoi', 1, 'Rumenește-le în ulei, într-o cratiță, 5 minute pe fiecare parte.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pulpe-de-pui-cu-sos-de-usturoi:s3', 'pulpe-de-pui-cu-sos-de-usturoi', 2, 'Adaugă 300 ml de apă, acoperă și înăbușă la foc mic 30 de minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pulpe-de-pui-cu-sos-de-usturoi:s4', 'pulpe-de-pui-cu-sos-de-usturoi', 3, 'Pisează usturoiul cu un praf de sare și amestecă-l cu 100 ml de apă. Toarnă-l peste pui, lasă să dea un clocot 2–3 minute și presară pătrunjel.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-pui-cu-legume:s1', 'ciorba-de-pui-cu-legume', 0, 'Pune pulpele în 3 l de apă rece cu sare și fierbe-le la foc mic 30 de minute, luând spuma.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-pui-cu-legume:s2', 'ciorba-de-pui-cu-legume', 1, 'Adaugă ceapa, morcovii, păstârnacul, țelina și ardeiul tăiate cubulețe și fierbe 15 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-pui-cu-legume:s3', 'ciorba-de-pui-cu-legume', 2, 'Pune cartofii cubulețe și roșiile și fierbe încă 15 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-pui-cu-legume:s4', 'ciorba-de-pui-cu-legume', 3, 'Scoate carnea, dezosează-o și pune-o înapoi în oală. Toarnă borșul fiert separat și lasă să dea un clocot.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ciorba-de-pui-cu-legume:s5', 'ciorba-de-pui-cu-legume', 4, 'Potrivește de sare și presară leușteanul tocat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gulas-de-vita:s1', 'gulas-de-vita', 0, 'Taie carnea cuburi de 2–3 cm și ceapa mărunt.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gulas-de-vita:s2', 'gulas-de-vita', 1, 'Călește ceapa în ulei 8 minute, până se îngălbenește. Adaugă carnea și rumenește-o 5 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gulas-de-vita:s3', 'gulas-de-vita', 2, 'Ia oala de pe foc, presară boiaua și chimenul și amestecă, ca să nu se ardă boiaua. Pune pasta de tomate, usturoiul și 1,5 l de apă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gulas-de-vita:s4', 'gulas-de-vita', 3, 'Fierbe la foc mic, acoperit, 1 oră, până se înmoaie carnea.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gulas-de-vita:s5', 'gulas-de-vita', 4, 'Adaugă morcovul, ardeii și cartofii cubulețe și încă 500 ml de apă, dacă e nevoie. Fierbe 25–30 de minute și potrivește cu sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocanita-de-vita:s1', 'tocanita-de-vita', 0, 'Taie carnea cuburi de 3 cm și rumenește-o în ulei, pe rând, câte puțină, ca să nu fiarbă. Scoate-o pe o farfurie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocanita-de-vita:s2', 'tocanita-de-vita', 1, 'În aceeași oală călește ceapa tocată 10 minute, la foc mic. Adaugă usturoiul și boiaua.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocanita-de-vita:s3', 'tocanita-de-vita', 2, 'Pune carnea înapoi, toarnă vinul și lasă-l să scadă 2 minute. Adaugă bulionul, cimbrul, dafinul și apă cât să acopere carnea.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocanita-de-vita:s4', 'tocanita-de-vita', 3, 'Înăbușă la foc mic, acoperit, 1 oră și jumătate – 2 ore, până se înmoaie carnea. Adaugă apă dacă scade prea mult.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocanita-de-vita:s5', 'tocanita-de-vita', 4, 'Potrivește de sare și piper și lasă sosul să se îngroașe 10 minute, descoperit.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cotlete-de-porc-cu-ceapa:s1', 'cotlete-de-porc-cu-ceapa', 0, 'Crestează marginea cotletelor, ca să nu se strângă, și condimentează-le cu sare, piper și cimbru.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cotlete-de-porc-cu-ceapa:s2', 'cotlete-de-porc-cu-ceapa', 1, 'Rumenește-le în ulei încins 4 minute pe fiecare parte și scoate-le pe o farfurie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cotlete-de-porc-cu-ceapa:s3', 'cotlete-de-porc-cu-ceapa', 2, 'În aceeași tigaie călește ceapa tăiată julienne 10 minute, la foc mic, până se îndulcește.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cotlete-de-porc-cu-ceapa:s4', 'cotlete-de-porc-cu-ceapa', 3, 'Pune cotletele înapoi peste ceapă, toarnă vinul sau 100 ml de apă, acoperă și lasă 8 minute, la foc mic.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ceafa-de-porc-la-gratar:s1', 'ceafa-de-porc-la-gratar', 0, 'Freacă feliile de ceafă cu 2 linguri de ulei, 2 căței de usturoi pisați, cimbru, boia și piper. Lasă-le la frigider cel puțin o oră.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ceafa-de-porc-la-gratar:s2', 'ceafa-de-porc-la-gratar', 1, 'Pentru mujdei, pisează usturoiul rămas cu un praf de sare, apoi adaugă 2 linguri de ulei și 3–4 linguri de apă rece, amestecând.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ceafa-de-porc-la-gratar:s3', 'ceafa-de-porc-la-gratar', 2, 'Încinge grătarul sau tigaia-grill și sărează carnea chiar înainte s-o pui pe foc.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ceafa-de-porc-la-gratar:s4', 'ceafa-de-porc-la-gratar', 3, 'Frige feliile 5–6 minute pe fiecare parte, până nu mai sunt roz la mijloc. Servește-le cu mujdei și murături.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('coaste-de-porc-la-cuptor:s1', 'coaste-de-porc-la-cuptor', 0, 'Încinge cuptorul la 160 °C. Freacă coastele cu sare, piper, boia și usturoi pisat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('coaste-de-porc-la-cuptor:s2', 'coaste-de-porc-la-cuptor', 1, 'Pune-le într-o tavă, toarnă 200 ml de apă, acoperă cu folie de aluminiu și coace 2 ore.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('coaste-de-porc-la-cuptor:s3', 'coaste-de-porc-la-cuptor', 2, 'Amestecă ketchupul cu mierea, muștarul și oțetul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('coaste-de-porc-la-cuptor:s4', 'coaste-de-porc-la-cuptor', 3, 'Scoate folia, unge coastele cu sos și dă cuptorul la 210 °C. Coace încă 20–25 de minute, ungând o dată, până se glazurează.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-marinate:s1', 'chiftele-marinate', 0, 'Amestecă carnea cu cartoful ras și stors, o ceapă rasă, oul, 2 căței de usturoi pisați, pătrunjel, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-marinate:s2', 'chiftele-marinate', 1, 'Formează chiftele ovale, dă-le prin făină și prăjește-le în ulei 3–4 minute pe fiecare parte. Păstrează 2 linguri de făină.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-marinate:s3', 'chiftele-marinate', 2, 'Într-o cratiță, călește cealaltă ceapă tocată în 3 linguri din uleiul de la prăjit. Presară făina păstrată și amestecă un minut.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-marinate:s4', 'chiftele-marinate', 3, 'Adaugă bulionul, 400 ml de apă, cimbrul, dafinul, zahărul, usturoiul rămas și sare. Fierbe sosul 5 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-marinate:s5', 'chiftele-marinate', 4, 'Pune chiftelele în sos și fierbe la foc mic 15 minute, până se îngroașă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ficatei-de-pui-cu-ceapa:s1', 'ficatei-de-pui-cu-ceapa', 0, 'Curăță ficățeii de pieliță și usucă-i cu un prosop de hârtie. Dă-i ușor prin făină.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ficatei-de-pui-cu-ceapa:s2', 'ficatei-de-pui-cu-ceapa', 1, 'Călește ceapa tăiată julienne în jumătate din ulei, 8 minute, și scoate-o.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ficatei-de-pui-cu-ceapa:s3', 'ficatei-de-pui-cu-ceapa', 2, 'Pune restul de ulei și rumenește ficățeii la foc mare 2–3 minute pe fiecare parte.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ficatei-de-pui-cu-ceapa:s4', 'ficatei-de-pui-cu-ceapa', 3, 'Adaugă ceapa înapoi, toarnă vinul și lasă 2 minute să scadă. Sărează abia acum, ca să rămână fragezi, și presară piper și pătrunjel.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocanita-de-pui:s1', 'tocanita-de-pui', 0, 'Taie carnea bucăți mari și rumenește-o în ulei 6–7 minute. Scoate-o pe o farfurie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocanita-de-pui:s2', 'tocanita-de-pui', 1, 'În aceeași cratiță călește ceapa tocată și ardeiul 8 minute, la foc mic.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocanita-de-pui:s3', 'tocanita-de-pui', 2, 'Adaugă boiaua, usturoiul, bulionul, cimbrul, dafinul și 300 ml de apă. Pune carnea înapoi.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tocanita-de-pui:s4', 'tocanita-de-pui', 3, 'Înăbușă la foc mic, acoperit, 30 de minute, până se înmoaie carnea și se leagă sosul. Potrivește de sare și presară pătrunjel.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('dovlecei-umpluti-cu-carne:s1', 'dovlecei-umpluti-cu-carne', 0, 'Taie dovleceii în jumătăți pe lungime și scobește miezul cu o linguriță, lăsând pereți de 1 cm. Toacă miezul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('dovlecei-umpluti-cu-carne:s2', 'dovlecei-umpluti-cu-carne', 1, 'Călește ceapa tocată și miezul de dovlecel în ulei 5 minute. Amestecă-le cu carnea, orezul spălat, oul, mărarul, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('dovlecei-umpluti-cu-carne:s3', 'dovlecei-umpluti-cu-carne', 2, 'Umple bărcuțele și așază-le într-o tavă. Toarnă în jur bulionul amestecat cu 200 ml de apă și puțină sare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('dovlecei-umpluti-cu-carne:s4', 'dovlecei-umpluti-cu-carne', 3, 'Acoperă cu folie și coace la 190 °C 35 de minute. Scoate folia, presară cașcavalul și mai coace 10 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('musaca-de-vinete:s1', 'musaca-de-vinete', 0, 'Taie vinetele felii de 1 cm, sărează-le și lasă-le 20 de minute. Clătește-le, usucă-le și rumenește-le în tigaie, cu puțin ulei, sau coace-le în cuptor, unse cu ulei, 15 minute la 200 °C.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('musaca-de-vinete:s2', 'musaca-de-vinete', 1, 'Călește ceapa tocată în 2 linguri de ulei 5 minute. Adaugă carnea și gătește-o 8 minute, apoi roșiile, usturoiul, sare și piper și fierbe 10 minute. Presară pătrunjel.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('musaca-de-vinete:s3', 'musaca-de-vinete', 2, 'Pentru sos, topește untul, adaugă făina și apoi laptele treptat, amestecând până se îngroașă. Ia de pe foc și încorporează ouăle bătute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('musaca-de-vinete:s4', 'musaca-de-vinete', 3, 'Într-o tavă unsă pune un strat de vinete, carnea, apoi încă un strat de vinete. Toarnă sosul alb și presară cașcavalul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('musaca-de-vinete:s5', 'musaca-de-vinete', 4, 'Coace la 180 °C 35–40 de minute, până se rumenește. Las-o 15 minute înainte s-o tai.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('piept-de-curcan-cu-legume-la-cuptor:s1', 'piept-de-curcan-cu-legume-la-cuptor', 0, 'Încinge cuptorul la 210 °C.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('piept-de-curcan-cu-legume-la-cuptor:s2', 'piept-de-curcan-cu-legume-la-cuptor', 1, 'Taie cartofii dulci cuburi de 2 cm, ardeii, ceapa și dovlecelul în bucăți mari. Amestecă-le într-o tavă cu jumătate din ulei, sare și cimbru și coace-le 15 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('piept-de-curcan-cu-legume-la-cuptor:s3', 'piept-de-curcan-cu-legume-la-cuptor', 2, 'Taie curcanul cuburi de 3 cm și amestecă-l cu uleiul rămas, boiaua, usturoiul pisat, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('piept-de-curcan-cu-legume-la-cuptor:s4', 'piept-de-curcan-cu-legume-la-cuptor', 3, 'Pune carnea printre legume și coace încă 18–20 de minute, până se rumenește și e pătrunsă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('carnati-cu-varza-murata:s1', 'carnati-cu-varza-murata', 0, 'Gustă varza: dacă e prea sărată, clătește-o în apă rece și stoarce-o. Taie-o fideluță.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('carnati-cu-varza-murata:s2', 'carnati-cu-varza-murata', 1, 'Călește ceapa tocată în ulei 5 minute, adaugă varza și călește-o 10 minute, amestecând.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('carnati-cu-varza-murata:s3', 'carnati-cu-varza-murata', 2, 'Pune bulionul, cimbrul, dafinul, piperul boabe și 200 ml de apă și mută varza într-o tavă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('carnati-cu-varza-murata:s4', 'carnati-cu-varza-murata', 3, 'Așază cârnații deasupra, înțepați cu furculița, și coace la 180 °C 40–45 de minute, întorcându-i o dată.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('burgeri-de-vita:s1', 'burgeri-de-vita', 0, 'Împarte carnea în 4 și formează chiftele de 2 cm grosime, puțin mai late decât chifla. Fă o adâncitură cu degetul în mijloc, ca să nu se umfle.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('burgeri-de-vita:s2', 'burgeri-de-vita', 1, 'Încinge bine o tigaie, sărează și piperează chiftelele și frige-le 4 minute pe o parte.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('burgeri-de-vita:s3', 'burgeri-de-vita', 2, 'Întoarce-le, pune câte o felie de cașcaval și mai gătește 3–4 minute, acoperit.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('burgeri-de-vita:s4', 'burgeri-de-vita', 3, 'Taie chiflele și prăjește-le ușor pe partea tăiată. Pune pe ele salată, chiftea, roșie, ceapă, murături și sosurile preferate.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('file-de-merluciu-pane:s1', 'file-de-merluciu-pane', 0, 'Usucă bine fileurile cu un prosop de hârtie, taie-le în porții și condimentează-le cu sare, piper și puțină zeamă de lămâie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('file-de-merluciu-pane:s2', 'file-de-merluciu-pane', 1, 'Treci fiecare bucată prin făină, ou bătut și pesmet.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('file-de-merluciu-pane:s3', 'file-de-merluciu-pane', 2, 'Prăjește peștele în ulei încins, la foc mediu, 3 minute pe fiecare parte, până se rumenește.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('file-de-merluciu-pane:s4', 'file-de-merluciu-pane', 3, 'Scoate-l pe hârtie de bucătărie și servește-l cu felii de lămâie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('creveti-cu-usturoi:s1', 'creveti-cu-usturoi', 0, 'Usucă creveții cu un prosop de hârtie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('creveti-cu-usturoi:s2', 'creveti-cu-usturoi', 1, 'Încălzește uleiul cu untul într-o tigaie largă și pune usturoiul feliat și ardeiul iute. Gătește 1 minut, fără să se rumenească usturoiul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('creveti-cu-usturoi:s3', 'creveti-cu-usturoi', 2, 'Adaugă creveții și gătește-i 2 minute pe fiecare parte, până devin roz.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('creveti-cu-usturoi:s4', 'creveti-cu-usturoi', 3, 'Stropește cu zeamă de lămâie, sărează și presară pătrunjel tocat. Servește imediat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('dorada-la-cuptor:s1', 'dorada-la-cuptor', 0, 'Încinge cuptorul la 200 °C. Taie cartofii felii subțiri și ceapa rondele, amestecă-le cu jumătate din ulei, sare și piper și coace-le 15 minute într-o tavă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('dorada-la-cuptor:s2', 'dorada-la-cuptor', 1, 'Crestează peștii pe ambele părți, sărează-i și piperează-i pe dinafară și pe dinăuntru.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('dorada-la-cuptor:s3', 'dorada-la-cuptor', 2, 'Pune în burta fiecărui pește felii de lămâie, usturoi și câteva fire de rozmarin.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('dorada-la-cuptor:s4', 'dorada-la-cuptor', 3, 'Așază peștii peste cartofi, stropește-i cu uleiul rămas și coace încă 20 de minute, până se desface ușor carnea de pe os.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-de-peste:s1', 'chiftele-de-peste', 0, 'Toacă peștele mărunt cu cuțitul sau în robot, fără să-l faci pastă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-de-peste:s2', 'chiftele-de-peste', 1, 'Rade cartoful și ceapa și stoarce-le bine de zeamă. Amestecă-le cu peștele, oul, pâinea, mărarul tocat, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-de-peste:s3', 'chiftele-de-peste', 2, 'Cu mâinile ude, formează chiftele turtite și dă-le prin pesmet. Dacă amestecul e prea moale, ține-l 15 minute la rece.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('chiftele-de-peste:s4', 'chiftele-de-peste', 3, 'Prăjește chiftelele în ulei, la foc mediu, 3–4 minute pe fiecare parte. Servește-le cu lămâie și cu salată sau piure.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pui-cu-legume-la-wok:s1', 'pui-cu-legume-la-wok', 0, 'Pune orezul la fiert după indicațiile de pe pachet.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pui-cu-legume-la-wok:s2', 'pui-cu-legume-la-wok', 1, 'Taie puiul fâșii și amestecă-l cu o lingură de sos de soia și amidonul. Taie legumele fâșii subțiri și broccoli în buchețele mici.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pui-cu-legume-la-wok:s3', 'pui-cu-legume-la-wok', 2, 'Amestecă restul de sos de soia cu mierea, ghimbirul ras, usturoiul pisat și 3 linguri de apă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pui-cu-legume-la-wok:s4', 'pui-cu-legume-la-wok', 3, 'Încinge uleiul în wok sau într-o tigaie mare, la foc mare, și gătește puiul 4–5 minute. Scoate-l.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pui-cu-legume-la-wok:s5', 'pui-cu-legume-la-wok', 4, 'Pune legumele și sotează-le 3–4 minute, să rămână crocante. Adaugă puiul și sosul, amestecă un minut și presară ceapa verde. Servește cu orez.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-cartofi-cu-carnati:s1', 'mancare-de-cartofi-cu-carnati', 0, 'Taie cârnații rondele și rumenește-i în ulei 4 minute. Scoate-i pe o farfurie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-cartofi-cu-carnati:s2', 'mancare-de-cartofi-cu-carnati', 1, 'În aceeași oală călește ceapa tocată și ardeiul 5 minute. Adaugă boiaua și amestecă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-cartofi-cu-carnati:s3', 'mancare-de-cartofi-cu-carnati', 2, 'Pune cartofii tăiați cuburi, bulionul, dafinul și apă cât să-i acopere aproape. Fierbe la foc mic 20 de minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mancare-de-cartofi-cu-carnati:s4', 'mancare-de-cartofi-cu-carnati', 3, 'Adaugă cârnații și mai fierbe 10 minute, până se înmoaie cartofii și se îngroașă sosul. Potrivește de sare și presară pătrunjel.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-ton-cu-porumb:s1', 'salata-de-ton-cu-porumb', 0, 'Scurge tonul, porumbul și fasolea și clătește fasolea sub apă rece.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-ton-cu-porumb:s2', 'salata-de-ton-cu-porumb', 1, 'Taie ceapa roșie julienne subțire, roșiile în jumătăți și salata fâșii.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-ton-cu-porumb:s3', 'salata-de-ton-cu-porumb', 2, 'Amestecă uleiul cu zeama de lămâie, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-ton-cu-porumb:s4', 'salata-de-ton-cu-porumb', 3, 'Pune totul într-un bol mare, toarnă sosul și amestecă ușor, ca să rămână tonul în bucăți.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-sos-de-rosii-si-busuioc:s1', 'paste-cu-sos-de-rosii-si-busuioc', 0, 'Încălzește uleiul într-o tigaie adâncă și gătește usturoiul feliat 1 minut, la foc mic.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-sos-de-rosii-si-busuioc:s2', 'paste-cu-sos-de-rosii-si-busuioc', 1, 'Adaugă roșiile strivite, zahărul, sare și piper și fierbe sosul 15 minute, până se îngroașă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-sos-de-rosii-si-busuioc:s3', 'paste-cu-sos-de-rosii-si-busuioc', 2, 'Fierbe pastele în apă cu sare după timpul de pe pachet. Păstrează o cană din apa în care au fiert și scurge-le.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-sos-de-rosii-si-busuioc:s4', 'paste-cu-sos-de-rosii-si-busuioc', 3, 'Amestecă pastele cu sosul și cu frunzele de busuioc rupte. Dacă e prea gros, adaugă puțină apă de la paste. Servește cu parmezan.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-pui-si-broccoli:s1', 'paste-cu-pui-si-broccoli', 0, 'Pune pastele la fiert în apă cu sare. Cu 3 minute înainte să fie gata, adaugă buchețelele de broccoli în aceeași oală, apoi scurge totul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-pui-si-broccoli:s2', 'paste-cu-pui-si-broccoli', 1, 'Taie puiul fâșii, condimentează-l cu sare și piper și rumenește-l în ulei 6–7 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-pui-si-broccoli:s3', 'paste-cu-pui-si-broccoli', 2, 'Adaugă usturoiul pisat, apoi smântâna, și lasă să dea un clocot.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-pui-si-broccoli:s4', 'paste-cu-pui-si-broccoli', 3, 'Pune pastele și broccoli în tigaie, presară parmezanul și amestecă până se leagă sosul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-ciuperci-si-smantana:s1', 'paste-cu-ciuperci-si-smantana', 0, 'Pune pastele la fiert în apă cu sare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-ciuperci-si-smantana:s2', 'paste-cu-ciuperci-si-smantana', 1, 'Topește untul într-o tigaie mare și rumenește ciupercile feliate la foc mare 7–8 minute, până scade apa.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-ciuperci-si-smantana:s3', 'paste-cu-ciuperci-si-smantana', 2, 'Adaugă usturoiul pisat, apoi smântâna, sare și piper. Fierbe 2–3 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-ciuperci-si-smantana:s4', 'paste-cu-ciuperci-si-smantana', 3, 'Scurge pastele și amestecă-le cu sosul. Presară pătrunjel și parmezan.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-cascaval-la-cuptor:s1', 'paste-cu-cascaval-la-cuptor', 0, 'Fierbe pastele cu 2 minute mai puțin decât scrie pe pachet și scurge-le.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-cascaval-la-cuptor:s2', 'paste-cu-cascaval-la-cuptor', 1, 'Topește untul, adaugă făina și amestecă un minut. Toarnă laptele treptat, cu telul, și fierbe până se îngroașă sosul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-cascaval-la-cuptor:s3', 'paste-cu-cascaval-la-cuptor', 2, 'Ia de pe foc și pune 200 g de cașcaval, muștarul, sare și nucșoară. Amestecă până se topește.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-cascaval-la-cuptor:s4', 'paste-cu-cascaval-la-cuptor', 3, 'Amestecă pastele cu sosul și pune-le într-un vas de cuptor. Presară restul de cașcaval și pesmetul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-cu-cascaval-la-cuptor:s5', 'paste-cu-cascaval-la-cuptor', 4, 'Coace la 200 °C 15–20 de minute, până se rumenește deasupra.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-aglio-olio:s1', 'paste-aglio-olio', 0, 'Fierbe spaghetele în apă cu multă sare după timpul de pe pachet. Păstrează o cană din apa de la paste.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-aglio-olio:s2', 'paste-aglio-olio', 1, 'Între timp încălzește uleiul la foc mic și gătește usturoiul feliat subțire 2–3 minute, până devine abia auriu. Adaugă ardeiul iute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-aglio-olio:s3', 'paste-aglio-olio', 2, 'Pune spaghetele scurse în tigaie, cu jumătate de cană din apa de la fiert, și amestecă energic 1 minut, până se leagă sosul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('paste-aglio-olio:s4', 'paste-aglio-olio', 3, 'Presară pătrunjelul tocat și, dacă vrei, parmezan.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('taitei-cu-varza:s1', 'taitei-cu-varza', 0, 'Taie varza fideluță, freac-o cu puțină sare și las-o 10 minute, apoi stoarce-o.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('taitei-cu-varza:s2', 'taitei-cu-varza', 1, 'Călește ceapa tocată în ulei 3 minute, adaugă varza și zahărul și gătește la foc mic, amestecând des, 30–35 de minute, până devine aurie și dulce.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('taitei-cu-varza:s3', 'taitei-cu-varza', 2, 'Fierbe pastele în apă cu sare și scurge-le.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('taitei-cu-varza:s4', 'taitei-cu-varza', 3, 'Amestecă pastele cu varza, pune mult piper și potrivește de sare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-paste:s1', 'salata-de-paste', 0, 'Fierbe pastele în apă cu sare, scurge-le și clătește-le cu apă rece. Stropește-le cu o lingură de ulei.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-paste:s2', 'salata-de-paste', 1, 'Taie roșiile în jumătăți, castravetele cubulețe și ceapa mărunt. Scurge porumbul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-paste:s3', 'salata-de-paste', 2, 'Amestecă restul de ulei cu oțetul, oregano, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-paste:s4', 'salata-de-paste', 3, 'Pune totul într-un bol mare, toarnă sosul și amestecă. Ține salata la rece; se păstrează 2 zile.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cuscus-cu-legume:s1', 'cuscus-cu-legume', 0, 'Încinge cuptorul la 210 °C. Taie dovlecelul, ardeii și ceapa în bucăți, amestecă-le cu roșiile, 3 linguri de ulei, sare și piper și coace-le 20–25 de minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cuscus-cu-legume:s2', 'cuscus-cu-legume', 1, 'Pune cuscusul într-un bol, sărează și toarnă peste el 300 ml de apă clocotită. Acoperă și lasă 5 minute, apoi afânează-l cu furculița.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cuscus-cu-legume:s3', 'cuscus-cu-legume', 2, 'Amestecă cuscusul cu legumele coapte, uleiul rămas, zeama de lămâie și menta tocată.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cuscus-cu-legume:s4', 'cuscus-cu-legume', 3, 'Presară feta sfărâmată și servește cald sau rece.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-tabbouleh:s1', 'salata-tabbouleh', 0, 'Pune bulgurul într-un bol, toarnă peste el 200 ml de apă clocotită, acoperă și lasă 15 minute. Afânează-l și lasă-l să se răcească.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-tabbouleh:s2', 'salata-tabbouleh', 1, 'Toacă foarte mărunt pătrunjelul, menta și ceapa verde. Taie roșiile și castravetele cubulețe mici.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-tabbouleh:s3', 'salata-tabbouleh', 2, 'Amestecă zeama de lămâie cu uleiul, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-tabbouleh:s4', 'salata-tabbouleh', 3, 'Pune bulgurul peste verdeață și legume, toarnă sosul și amestecă bine. Las-o 15 minute înainte de servit.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-quinoa:s1', 'salata-de-quinoa', 0, 'Clătește quinoa într-o sită fină, apoi fierbe-o în 400 ml de apă cu sare, acoperită, 12–15 minute, până absoarbe apa. Las-o să se răcească.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-quinoa:s2', 'salata-de-quinoa', 1, 'Taie castravetele, ardeiul și ceapa cubulețe și roșiile în jumătăți.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-quinoa:s3', 'salata-de-quinoa', 2, 'Amestecă zeama de lămâie cu uleiul, sare și piper.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salata-de-quinoa:s4', 'salata-de-quinoa', 3, 'Amestecă quinoa cu legumele, pătrunjelul tocat și sosul, apoi sfărâmă feta deasupra.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('orez-prajit-cu-ou:s1', 'orez-prajit-cu-ou', 0, 'Taie morcovul cubulețe mici, ceapa verde rondele și pisează usturoiul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('orez-prajit-cu-ou:s2', 'orez-prajit-cu-ou', 1, 'Încinge jumătate din ulei într-o tigaie mare, bate ouăle și fă-le jumări moi. Scoate-le pe o farfurie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('orez-prajit-cu-ou:s3', 'orez-prajit-cu-ou', 2, 'Pune restul de ulei și sotează morcovul și mazărea 3 minute, la foc mare. Adaugă usturoiul și partea albă a cepei verzi.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('orez-prajit-cu-ou:s4', 'orez-prajit-cu-ou', 3, 'Pune orezul, desfă-l cu spatula și prăjește-l 3–4 minute. Adaugă sosul de soia, ouăle și restul de ceapă verde și amestecă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('wrap-cu-pui-si-legume:s1', 'wrap-cu-pui-si-legume', 0, 'Taie puiul fâșii, condimentează-l cu boia, sare și piper și rumenește-l în ulei 6–7 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('wrap-cu-pui-si-legume:s2', 'wrap-cu-pui-si-legume', 1, 'Amestecă iaurtul cu usturoiul pisat și un praf de sare.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('wrap-cu-pui-si-legume:s3', 'wrap-cu-pui-si-legume', 2, 'Taie salata fâșii, iar roșiile și castravetele felii subțiri. Încălzește lipiile în tigaie câteva secunde pe fiecare parte.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('wrap-cu-pui-si-legume:s4', 'wrap-cu-pui-si-legume', 3, 'Unge fiecare lipie cu sos, pune legumele și puiul, rulează-o strâns și taie-o în două.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ratatouille:s1', 'ratatouille', 0, 'Taie toate legumele cuburi de 2 cm.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ratatouille:s2', 'ratatouille', 1, 'Rumenește vinetele în 3 linguri de ulei, 6–7 minute, și scoate-le. Apoi rumenește dovleceii 4 minute și scoate-i.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ratatouille:s3', 'ratatouille', 2, 'În restul de ulei călește ceapa și ardeii 6 minute, adaugă usturoiul, roșiile și cimbrul și fierbe 10 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('ratatouille:s4', 'ratatouille', 3, 'Pune înapoi vinetele și dovleceii, sare și piper, și înăbușă la foc mic 15 minute. Presară busuioc rupt.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gnocchi-cu-sos-de-rosii:s1', 'gnocchi-cu-sos-de-rosii', 0, 'Fierbe cartofii în coajă până se înmoaie, curăță-i cât sunt calzi și pasează-i. Lasă piureul să se răcească puțin.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gnocchi-cu-sos-de-rosii:s2', 'gnocchi-cu-sos-de-rosii', 1, 'Adaugă oul, un praf de sare și făina treptat, până obții un aluat moale care nu se mai lipește. Nu-l frământa mult.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gnocchi-cu-sos-de-rosii:s3', 'gnocchi-cu-sos-de-rosii', 2, 'Împarte aluatul, rulează-l în suluri groase cât degetul și taie bucăți de 2 cm. Presară-le cu făină.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gnocchi-cu-sos-de-rosii:s4', 'gnocchi-cu-sos-de-rosii', 3, 'Pentru sos, gătește usturoiul în ulei 1 minut, adaugă roșiile și sare și fierbe 10 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gnocchi-cu-sos-de-rosii:s5', 'gnocchi-cu-sos-de-rosii', 4, 'Fierbe găluștele în apă cu sare, în tranșe: când urcă la suprafață, mai lasă-le 30 de secunde și scoate-le cu spumiera direct în sos. Servește cu parmezan și busuioc.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-minestrone:s1', 'supa-minestrone', 0, 'Călește ceapa, morcovii și țelina tăiate cubulețe în ulei 6 minute. Adaugă usturoiul încă un minut.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-minestrone:s2', 'supa-minestrone', 1, 'Pune cartofii cubulețe, roșiile și 2 l de apă cu sare. Fierbe 15 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-minestrone:s3', 'supa-minestrone', 2, 'Adaugă dovlecelul cubulețe și fasolea scursă și fierbe încă 8 minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('supa-minestrone:s4', 'supa-minestrone', 3, 'Pune pastele și fierbe-le după timpul de pe pachet. Potrivește cu sare și piper și servește cu busuioc și parmezan.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mere-coapte-cu-nuca:s1', 'mere-coapte-cu-nuca', 0, 'Încinge cuptorul la 180 °C. Spală merele și scoate-le cotorul cu un cuțit mic, fără să le găurești până jos.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mere-coapte-cu-nuca:s2', 'mere-coapte-cu-nuca', 1, 'Amestecă nucile tocate cu mierea, scorțișoara și stafidele.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mere-coapte-cu-nuca:s3', 'mere-coapte-cu-nuca', 2, 'Umple merele, pune câte o bucățică de unt deasupra și așază-le într-un vas cu 3–4 linguri de apă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('mere-coapte-cu-nuca:s4', 'mere-coapte-cu-nuca', 3, 'Coace-le 30–35 de minute, până se înmoaie. Servește-le calde, cu siropul din vas.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tiramisu:s1', 'tiramisu', 0, 'Fă 400 ml de cafea tare și las-o să se răcească complet.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tiramisu:s2', 'tiramisu', 1, 'Bate smântâna dulce rece cu jumătate din zahărul pudră până se face frișcă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tiramisu:s3', 'tiramisu', 2, 'Amestecă mascarpone cu restul de zahăr și vanilia, apoi încorporează frișca ușor, cu spatula.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tiramisu:s4', 'tiramisu', 3, 'Înmoaie pișcoturile o secundă în cafea și așază-le într-un vas. Pune jumătate din cremă, apoi încă un strat de pișcoturi și restul de cremă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('tiramisu:s5', 'tiramisu', 4, 'Acoperă vasul și ține-l la frigider cel puțin 6 ore. Presară cacao cu o sită chiar înainte de servit.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('negresa:s1', 'negresa', 0, 'Încinge cuptorul la 180 °C și tapetează o tavă de 25 × 30 cm cu hârtie de copt.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('negresa:s2', 'negresa', 1, 'Bate ouăle cu zahărul și zahărul vanilat până se albesc. Adaugă uleiul și laptele, amestecând.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('negresa:s3', 'negresa', 2, 'Amestecă făina cu cacaua și praful de copt și încorporează-le cu o lingură în compoziție.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('negresa:s4', 'negresa', 3, 'Toarnă în tavă și coace 25–30 de minute, până când o scobitoare iese aproape curată.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('negresa:s5', 'negresa', 4, 'Topește ciocolata cu untul pe baie de aburi și întinde glazura pe prăjitura răcită. Taie-o pătrate după ce se întărește.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gogosi:s1', 'gogosi', 0, 'Dizolvă drojdia în laptele călduț cu o lingură de zahăr și las-o 10 minute, până face spumă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gogosi:s2', 'gogosi', 1, 'Amestecă făina cu restul de zahăr, zahărul vanilat și un praf de sare. Adaugă drojdia, ouăle și untul și frământă 10 minute un aluat moale.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gogosi:s3', 'gogosi', 2, 'Acoperă aluatul și lasă-l la cald o oră, până își dublează volumul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gogosi:s4', 'gogosi', 3, 'Întinde-l la 1,5 cm grosime, decupează cercuri cu un pahar și lasă-le încă 20 de minute să crească.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('gogosi:s5', 'gogosi', 4, 'Prăjește gogoșile în ulei încins la foc mediu, 1–2 minute pe fiecare parte, până se rumenesc. Scoate-le pe hârtie și pudrează-le cu zahăr.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pandispan-cu-fructe:s1', 'pandispan-cu-fructe', 0, 'Încinge cuptorul la 180 °C și tapetează o tavă de 25 × 30 cm cu hârtie de copt.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pandispan-cu-fructe:s2', 'pandispan-cu-fructe', 1, 'Bate albușurile cu un praf de sare spumă tare, adaugând zahărul treptat. Pune gălbenușurile pe rând, apoi uleiul și zahărul vanilat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pandispan-cu-fructe:s3', 'pandispan-cu-fructe', 2, 'Încorporează ușor, cu spatula, făina amestecată cu praful de copt.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pandispan-cu-fructe:s4', 'pandispan-cu-fructe', 3, 'Toarnă aluatul în tavă și împrăștie fructele deasupra (pe cele congelate nu le decongela).', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('pandispan-cu-fructe:s5', 'pandispan-cu-fructe', 4, 'Coace 30–35 de minute, până se rumenește și o scobitoare iese curată. Pudrează cu zahăr după ce se răcește.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('fursecuri-cu-unt:s1', 'fursecuri-cu-unt', 0, 'Freacă untul rece tăiat cubulețe cu făina, zahărul pudră, zahărul vanilat și un praf de sare, până se face nisipos.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('fursecuri-cu-unt:s2', 'fursecuri-cu-unt', 1, 'Adaugă gălbenușul și coaja de lămâie și adună repede aluatul, fără să-l frămânți mult. Învelește-l în folie și ține-l la rece 30 de minute.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('fursecuri-cu-unt:s3', 'fursecuri-cu-unt', 2, 'Întinde aluatul la 4–5 mm pe o suprafață presărată cu făină și decupează forme.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('fursecuri-cu-unt:s4', 'fursecuri-cu-unt', 3, 'Coace fursecurile pe hârtie de copt la 180 °C 10–12 minute, până se rumenesc ușor marginile. Lasă-le să se răcească pe tavă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('lapte-de-pasare:s1', 'lapte-de-pasare', 0, 'Desparte ouăle. Bate albușurile spumă tare cu 50 g de zahăr.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('lapte-de-pasare:s2', 'lapte-de-pasare', 1, 'Încălzește laptele cu zahărul vanilat până aproape de fierbere. Pune cu lingura grămăjoare de albuș în lapte, fierbe-le 1 minut pe fiecare parte și scoate-le cu spumiera pe o farfurie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('lapte-de-pasare:s3', 'lapte-de-pasare', 2, 'Freacă gălbenușurile cu restul de zahăr și amidonul. Toarnă peste ele, puțin câte puțin, un polonic de lapte fierbinte, amestecând.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('lapte-de-pasare:s4', 'lapte-de-pasare', 3, 'Toarnă amestecul în laptele rămas și fierbe la foc mic, amestecând continuu, până se îngroașă ușor. Nu-l lăsa să clocotească.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('lapte-de-pasare:s5', 'lapte-de-pasare', 4, 'Pune crema în boluri, cu insulițele de albuș deasupra, și las-o la rece cel puțin 2 ore.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salam-de-biscuiti:s1', 'salam-de-biscuiti', 0, 'Sfărâmă biscuiții cu mâna în bucăți de diferite mărimi. Taie rahatul cubulețe și toacă nucile grosier.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salam-de-biscuiti:s2', 'salam-de-biscuiti', 1, 'Încălzește laptele cu zahărul, untul și cacaua, amestecând, până se topește totul. Nu-l lăsa să fiarbă mult. Adaugă esența de rom.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salam-de-biscuiti:s3', 'salam-de-biscuiti', 2, 'Toarnă siropul cald peste biscuiți, nuci și rahat și amestecă bine.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('salam-de-biscuiti:s4', 'salam-de-biscuiti', 3, 'Pune compoziția pe folie alimentară, rulează un sul strâns și ține-l la frigider cel puțin 4 ore. Taie-l felii.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cheesecake-fara-coacere:s1', 'cheesecake-fara-coacere', 0, 'Sfărâmă biscuiții fin, amestecă-i cu untul topit și presează-i pe fundul unei forme de 22 cm cu fundul detașabil. Pune forma la rece.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cheesecake-fara-coacere:s2', 'cheesecake-fara-coacere', 1, 'Hidratează gelatina după indicațiile de pe plic și dizolv-o la foc mic, fără să fiarbă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cheesecake-fara-coacere:s3', 'cheesecake-fara-coacere', 2, 'Bate crema de brânză cu zahărul pudră, zeama și coaja de lămâie. Separat, bate smântâna dulce frișcă.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cheesecake-fara-coacere:s4', 'cheesecake-fara-coacere', 3, 'Amestecă gelatina călduță cu 2 linguri de cremă, apoi cu toată crema de brânză. Încorporează frișca ușor și toarnă peste blat.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('cheesecake-fara-coacere:s5', 'cheesecake-fara-coacere', 4, 'Ține prăjitura la frigider cel puțin 6 ore. Fierbe fructele de pădure cu zahărul 5 minute, lasă sosul să se răcească și pune-l deasupra înainte de servit.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('crema-de-zahar-ars:s1', 'crema-de-zahar-ars', 0, 'Topește 150 g de zahăr într-o cratiță, la foc mediu, fără să amesteci, până devine caramel auriu. Toarnă-l repede într-o formă de chec sau în 6 forme mici și înclină-le să acopere fundul.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('crema-de-zahar-ars:s2', 'crema-de-zahar-ars', 1, 'Încălzește laptele cu zahărul vanilat. Bate ușor ouăle cu restul de zahăr, fără să faci spumă, și toarnă laptele cald peste ele, amestecând.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('crema-de-zahar-ars:s3', 'crema-de-zahar-ars', 2, 'Strecoară compoziția și toarn-o peste caramel.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('crema-de-zahar-ars:s4', 'crema-de-zahar-ars', 3, 'Pune formele într-o tavă mai mare cu apă fierbinte până la jumătatea lor și coace la 160 °C 40–45 de minute, până se leagă crema, dar încă tremură ușor la mijloc.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z'),
  ('crema-de-zahar-ars:s5', 'crema-de-zahar-ars', 4, 'Lasă crema să se răcească, apoi ține-o la frigider cel puțin 4 ore. Treci un cuțit pe margini și răstoarn-o pe o farfurie.', '2026-10-19T09:00:00.000Z', '2026-10-19T09:00:00.000Z')
